window.VRAGEN_DATA=(window.VRAGEN_DATA||[]).concat([
 {id:'vbe-001',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-03T09:25:00',views:470,tags:['aflossingseis','annuitair','lineair'],beste:'vbe-001-a1',
  titel:'Aflossingseis bij nieuwe lening: annuitair of lineair voor renteaftrek?',
  body:`Een starter twijfelt tussen een annuitaire en een lineaire hypotheek. Klopt het dat beide vormen voldoen aan de aflossingseis voor de renteaftrek? En moet de aflossing echt contractueel vastliggen?`,
  antwoorden:[
   {id:'vbe-001-a1',auteur:'u1',datum:'2025-10-03T15:20:00',rA:{},rAdv:{},body:`Ja, beide vormen voldoen. De eis is dat de lening in maximaal 30 jaar ten minste annuitair wordt afgelost; lineair lost sneller af en voldoet daarmee ook.
- Het aflossingsschema moet in de leningsovereenkomst staan.
- De klant moet het schema ook daadwerkelijk volgen.
In het dossier leg ik de leningvorm, de looptijd en de toelichting op het verschil in netto maandlasten vast.`},
   {id:'vbe-001-a2',auteur:'u5',datum:'2025-10-04T23:35:00',rA:{u3:3,u4:5,u2:4,u8:5},rAdv:{u2:4},body:`Aanvulling: laat de klant de netto lasten over de hele looptijd zien. Bij lineair zijn de lasten in het begin hoger, wat de betaalbaarheid in de eerste jaren raakt. Controleer daarnaast de voorwaarden van de geldverstrekker over boetevrij extra aflossen, want dat speelt bij de keuze vaak mee.`}
  ]},
 {id:'vbe-002',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-05T20:45:00',views:580,tags:['overgangsrecht','verhuizen','aflossingsvrij'],beste:'vbe-002-a1',
  titel:'Overgangsrecht meenemen bij verhuizing naar duurdere woning',
  body:`Een klant heeft een aflossingsvrije lening uit 2008 en verhuist naar een duurdere woning. Hoeveel van de nieuwe financiering mag aflossingsvrij blijven? En wat gebeurt er met de overwaarde uit de oude woning?`,
  antwoorden:[
   {id:'vbe-002-a1',auteur:'u5',datum:'2025-10-06T12:55:00',rA:{},rAdv:{},body:`Het overgangsrecht gaat mee tot maximaal het bedrag van de bestaande eigenwoningschuld op het moment van verkoop. Het meerdere moet voldoen aan de aflossingseis.
Let op de bijleenregeling: de eigenwoningreserve uit de verkoop moet je eerst in de nieuwe woning stoppen, anders valt een deel van de lening in box 3.
Ik maak altijd een berekening met de verkoopprijs min verkoopkosten min de oude eigenwoningschuld en leg die vast in het dossier.`},
   {id:'vbe-002-a2',auteur:'u4',datum:'2025-10-06T15:25:00',rA:{u3:5},rAdv:{u3:5},body:`Eens met bovenstaande. Vraag de klant om de leningoverzichten per 31 december 2012 en de opgave van de huidige geldverstrekker, zodat je het bedrag met overgangsrecht kunt onderbouwen. Controleer bij de nieuwe geldverstrekker of zij het aflossingsvrije deel onder dezelfde voorwaarden accepteren.`}
  ]},
 {id:'vbe-003',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-09T09:55:00',views:529,tags:['eigenwoningreserve','bijleenregeling','verbouwing'],beste:null,
  titel:'Eigenwoningreserve berekenen bij verkoop met verlies op eerdere verbouwing',
  body:`De klant verkoopt een woning waar destijds flink in is verbouwd, deels uit eigen geld. Telt die eigen inbreng mee bij de berekening van de eigenwoningreserve? Of is het puur verkoopprijs min kosten min schuld?`,
  antwoorden:[
   {id:'vbe-003-a1',auteur:'u5',datum:'2025-10-09T17:00:00',rA:{u1:5},rAdv:{u1:5},body:`Het is in principe puur de rekensom: verkoopprijs min verkoopkosten min de eigenwoningschuld. Eigen geld dat in de woning is gestoken verlaagt de EWR niet. Dat voelt voor klanten vaak oneerlijk, dus leg het goed uit en leg de berekening vast. Bij twijfel over de verkoopkosten zou ik de actuele toelichting van de Belastingdienst erbij pakken.`},
   {id:'vbe-003-a2',auteur:'u2',datum:'2025-10-10T02:50:00',rA:{u8:4},rAdv:{u8:4},body:`Kleine nuance: in sommige situaties, bijvoorbeeld bij een eerder verlies op een woning, kan een andere berekening spelen. Ga dat na voordat je de klant een definitief getal geeft en noteer welke bronnen je hebt gebruikt.`}
  ]},
 {id:'vbe-004',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-14T14:35:00',views:276,tags:['dubbele lasten','leegstand','verkoop'],beste:'vbe-004-a1',
  titel:'Dubbele woonlasten: hoe lang aftrek op de oude woning?',
  body:`Een klant heeft een nieuwe woning gekocht en de oude woning staat leeg en te koop. Hoe lang mag de rente op de lening van de oude woning nog worden afgetrokken? Moet de woning aantoonbaar te koop staan?`,
  antwoorden:[
   {id:'vbe-004-a1',auteur:'u1',datum:'2025-10-17T03:45:00',rA:{u3:5,u4:3},rAdv:{u3:5},body:`Zolang de oude woning leeg staat en te koop staat, blijft deze voor de aftrek een eigen woning, tot en met het derde jaar na het jaar waarin de woning leeg kwam te staan. Controleer wel de actuele voorwaarden.
- Woning moet leeg staan; tijdelijke verhuur doorbreekt dit.
- Leg vast dat de woning in de verkoop staat, bijvoorbeeld met de opdracht aan de makelaar.`},
   {id:'vbe-004-a2',auteur:'u8',datum:'2025-10-17T07:00:00',rA:{},rAdv:{},body:`Vanuit compliance: noteer in het advies welke periode je hebt aangehouden in de lastenberekening en wat er gebeurt als de woning later verkoopt. Dan kan de klant het risico van dubbele lasten zelf goed inschatten.`}
  ]},
 {id:'vbe-005',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-17T09:25:00',views:400,tags:['bouwdepot','nieuwbouw','renteaftrek'],beste:'vbe-005-a1',
  titel:'Bouwdepot en renteaftrek bij nieuwbouw',
  body:`Bij een nieuwbouwwoning loopt het bouwdepot nog. Is de rente over het deel in het bouwdepot aftrekbaar, terwijl de klant nog niet in de woning woont? En hoe zit het met de rentevergoeding over het depot?`,
  antwoorden:[
   {id:'vbe-005-a1',auteur:'u4',datum:'2025-10-19T08:30:00',rA:{u1:5,u7:5},rAdv:{u1:5},body:`Een woning in aanbouw kan voor maximaal drie jaar als eigen woning gelden, mits de klant er na oplevering gaat wonen. De rente is aftrekbaar, maar de rentevergoeding over het bouwdepot moet je in mindering brengen op de aftrekbare rente.
Ik leg in het dossier de verwachte opleverdatum vast en wijs de klant op de jaaropgave van de geldverstrekker.`},
   {id:'vbe-005-a2',auteur:'u5',datum:'2025-10-19T17:30:00',rA:{u1:5,u8:4},rAdv:{u1:5,u8:4},body:`Goed punt van de verrekening. Klanten vergeten die vaak in de aangifte. Ik stuur standaard een korte toelichting mee na het passeren.`}
  ]},
 {id:'vbe-006',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-22T09:45:00',views:257,tags:['financieringskosten','kosten koper','aangifte'],beste:'vbe-006-a1',
  titel:'Financieringskosten aftrekbaar in jaar van aankoop',
  body:`Welke kosten bij aankoop kan de klant in het jaar van passeren aftrekken? Ik twijfel over de taxatiekosten en de kosten van de leveringsakte.`,
  antwoorden:[
   {id:'vbe-006-a1',auteur:'u1',datum:'2025-10-23T11:55:00',rA:{u5:3},rAdv:{u5:3},body:`Aftrekbaar als financieringskosten zijn onder andere:
- advies- en bemiddelingskosten voor de hypotheek
- notariskosten voor de hypotheekakte
- taxatiekosten die nodig zijn voor de lening
- de borgtochtprovisie bij NHG
Niet aftrekbaar zijn de overdrachtsbelasting en de kosten van de leveringsakte. Die mag de klant wel meefinancieren als onderdeel van de eigenwoningschuld.`},
   {id:'vbe-006-a2',auteur:'u2',datum:'2025-10-24T11:25:00',rA:{u7:4},rAdv:{u7:4},body:`Aanvulling: laat de klant de notarisafrekening bewaren, want daar staat de splitsing tussen leverings- en hypotheekakte in. Dat scheelt discussie bij een eventuele controle.`}
  ]},
 {id:'vbe-007',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-23T13:25:00',views:469,tags:['overgangsrecht','huren','herleven'],beste:null,
  titel:'Overgangsrecht na periode van huren: termijn voor herleven',
  body:`Een klant heeft in 2019 de woning verkocht en is gaan huren. Nu wil hij weer kopen. Hij had een aflossingsvrije lening uit 2006. Kan hij het overgangsrecht nog gebruiken en zo ja tot welk bedrag?`,
  antwoorden:[]},
 {id:'vbe-008',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-28T19:40:00',views:535,tags:['verbouwing','eigenwoningschuld','bouwdepot'],beste:'vbe-008-a1',
  titel:'Bijlenen voor verbouwing: is de lening eigenwoningschuld?',
  body:`Een klant wil extra lenen voor een nieuwe keuken en een aanbouw. Valt dat volledig onder de eigenwoningschuld? En hoe toon je aan dat het geld echt in de woning is gestoken?`,
  antwoorden:[
   {id:'vbe-008-a1',auteur:'u4',datum:'2025-10-30T07:35:00',rA:{},rAdv:{},body:`Een lening voor verbetering of onderhoud van de eigen woning kan eigenwoningschuld zijn, mits het geld daar ook echt aan wordt besteed en de nieuwe lening voldoet aan de aflossingseis. Een bouwdepot maakt de besteding goed aantoonbaar.
Ik adviseer de klant facturen en betaalbewijzen te bewaren en leg de verbouwingsspecificatie vast in het dossier.`},
   {id:'vbe-008-a2',auteur:'u1',datum:'2025-10-30T14:30:00',rA:{},rAdv:{},body:`Let ook op inventaris: losse apparatuur en meubilair tellen niet als verbetering van de woning. Een ingebouwde keuken doorgaans wel, maar controleer dit per situatie.`}
  ]},
 {id:'vbe-009',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-01T13:05:00',views:231,tags:['aflossingsachterstand','aflossingseis','herstel'],beste:null,
  titel:'Aflossingsachterstand op annuitaire lening: verlies van aftrek?',
  body:`Een klant heeft door tijdelijke inkomensdaling enkele maanden de aflossing niet betaald, wel de rente. Verliest hij nu direct de renteaftrek? Wat is de termijn om dit te herstellen?`,
  antwoorden:[
   {id:'vbe-009-a1',auteur:'u5',datum:'2025-11-02T21:50:00',rA:{u7:5,u3:5,u4:4},rAdv:{u7:5,u3:5},body:`Niet direct. Als de achterstand wordt ingehaald uiterlijk aan het eind van het volgende kalenderjaar, blijft de lening voldoen. Lukt dat niet, dan gaat het deel van de lening dat niet volgens schema is afgelost naar box 3.
Controleer de actuele regels en spreek met de klant een concreet herstelplan af. Ik noteer de afspraak en de datum in het dossier.`}
  ]},
 {id:'vbe-010',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-05T15:15:00',views:414,tags:['overgangsrecht','samenwonen','partner'],beste:'vbe-010-a1',
  titel:'Partner gaat samenwonen met eigenaar met overgangsrecht',
  body:`Een klant met overgangsrecht gaat samenwonen. De partner gaat mee-eigenaar worden en er wordt een nieuwe lening gesloten voor het aandeel. Neemt de partner het overgangsrecht mee?`,
  antwoorden:[
   {id:'vbe-010-a1',auteur:'u5',datum:'2025-11-06T05:40:00',rA:{u8:4},rAdv:{u8:4},body:`Nee, het overgangsrecht is persoonsgebonden. De partner heeft zelf geen bestaande eigenwoningschuld, dus voor de nieuwe lening van de partner geldt de aflossingseis. De klant met overgangsrecht houdt dat voor zijn deel.
Leg in het dossier per persoon vast welk deel onder overgangsrecht valt en hoe de leningdelen zijn toegerekend.`},
   {id:'vbe-010-a2',auteur:'u2',datum:'2025-11-06T09:25:00',rA:{u7:5,u4:3},rAdv:{},body:`Denk ook aan de verdeling van de aftrek: fiscale partners mogen de aftrek en het eigenwoningforfait onderling vrij verdelen. Dat is iets anders dan wie welke lening heeft, maar klanten halen het vaak door elkaar.`},
   {id:'vbe-010-a3',auteur:'u8',datum:'2025-11-07T22:25:00',rA:{u1:3,u7:5,u2:4,u4:5},rAdv:{u1:3,u7:5,u2:4,u4:5},body:`Laat de samenlevingsovereenkomst of het testament mee nemen in je inventarisatie. Bij een scheiding of overlijden speelt de verdeling van de leningdelen anders een grote rol.`}
  ]},
 {id:'vbe-011',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-09T14:05:00',views:224,tags:['restschuld','aftrek','overgangsregeling'],beste:'vbe-011-a1',
  titel:'Restschuld na verkoop in 2016: hoe lang nog aftrek?',
  body:`Een klant heeft in 2016 de woning verkocht met een restschuld en die restschuld is gefinancierd. Hoe lang is de rente hierover nog aftrekbaar? En geldt hier ook een aflossingseis?`,
  antwoorden:[
   {id:'vbe-011-a1',auteur:'u5',datum:'2025-11-11T02:40:00',rA:{u3:4,u7:5},rAdv:{},body:`Voor restschulden van woningen verkocht tussen 29 oktober 2012 en eind 2017 is de rente op de restschuldfinanciering maximaal 15 jaar aftrekbaar in box 1. Voor de precieze voorwaarden rond aflossing zou ik de actuele regelgeving raadplegen, daar ben ik niet zeker genoeg over om het hier stellig te zeggen.
Ik leg in het dossier vast wanneer de woning is verkocht en hoe hoog de restschuld was.`}
  ]},
 {id:'vbe-012',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-12T08:55:00',views:501,tags:['restschuld','box 3','verkoop'],beste:null,
  titel:'Restschuld bij verkoop dit jaar: box 3?',
  body:`Een klant moet de woning verkopen met verlies. Hoe wordt de restschuld fiscaal behandeld? Is de rente nog aftrekbaar?`,
  antwoorden:[
   {id:'vbe-012-a1',auteur:'u1',datum:'2025-11-13T09:25:00',rA:{u4:3},rAdv:{u4:3},body:`Voor restschulden die na 2017 ontstaan bestaat de box 1-regeling niet meer. De restschuld valt in box 3 als schuld. Of dat fiscaal voordeel oplevert hangt af van het overige vermogen en de actuele drempel voor schulden.
Bespreek ook met de geldverstrekker welke afbetalingsregeling mogelijk is en leg vast wat je de klant hebt toegelicht.`},
   {id:'vbe-012-a2',auteur:'u2',datum:'2025-11-14T16:55:00',rA:{u7:5,u3:5,u4:5,u8:4},rAdv:{u4:5},body:`Eens. Neem dit ook mee in het budgetadvies, want zonder aftrek zijn de netto lasten van een restschuld vaak hoger dan klanten verwachten.`}
  ]},
 {id:'vbe-013',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-16T15:00:00',views:201,tags:['fiscaal partnerschap','verdeling','aangifte'],beste:'vbe-013-a1',
  titel:'Fiscale partners: verdeling van renteaftrek en eigenwoningforfait',
  body:`Twee fiscale partners hebben samen een woning met de lening op beider naam. De een verdient veel meer dan de ander. Mag de aftrek volledig bij de hoogste verdiener?`,
  antwoorden:[
   {id:'vbe-013-a1',auteur:'u2',datum:'2025-11-17T05:30:00',rA:{},rAdv:{},body:`Ja, fiscale partners mogen de gezamenlijke inkomsten en aftrekposten uit de eigen woning onderling verdelen. Het voordeel van een verschuiving is wel beperkt doordat de aftrek tegen een gemaximeerd tarief plaatsvindt.
Ik reken dit door in de aangifte of de planning en noteer de gekozen verdeling.`},
   {id:'vbe-013-a2',auteur:'u4',datum:'2025-11-18T11:50:00',rA:{u5:4},rAdv:{u5:4},body:`Aanvulling: bij een minstverdienende partner met weinig inkomen kan de verdeling ook invloed hebben op heffingskortingen. Reken het altijd door voor beide partners.`}
  ]},
 {id:'vbe-014',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-20T10:20:00',views:593,tags:['Wet Hillen','aflossen','eigenwoningforfait'],beste:'vbe-014-a1',
  titel:'Wet Hillen bij bijna afgeloste woning',
  body:`Een klant heeft de hypotheek bijna volledig afgelost. Hij vraagt of hij nog extra aflossen of beter een kleine lening laten staan vanwege de Wet Hillen. Hoe pakken jullie dit gesprek aan?`,
  antwoorden:[
   {id:'vbe-014-a1',auteur:'u5',datum:'2025-11-21T18:10:00',rA:{},rAdv:{},body:`De aftrek wegens geen of geringe eigenwoningschuld wordt stapsgewijs afgebouwd. Daardoor gaat de klant bij volledig aflossen geleidelijk meer belasting betalen over het eigenwoningforfait. Reken met de actuele percentages uit wat het netto verschil is.
In de praktijk weegt het vrij beschikbaar houden van geld of het rendement daarop vaak zwaarder dan het fiscale effect. Ik leg de vergelijking en de keuze van de klant vast.`},
   {id:'vbe-014-a2',auteur:'u2',datum:'2025-11-22T15:40:00',rA:{u8:3,u4:5,u3:5,u1:3},rAdv:{u8:3,u4:5,u3:5,u1:3},body:`Neem ook de wens van de klant mee om schuldenvrij te zijn. Dat is een legitiem doel, ook als het fiscaal niet optimaal is.`}
  ]},
 {id:'vbe-015',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-21T07:05:00',views:258,tags:['aftrekperiode','oversluiten','looptijd'],beste:'vbe-015-a1',
  titel:'Aftrekperiode van 30 jaar bij oversluiten',
  body:`Bij oversluiten van een lening uit 2015 met een nieuwe looptijd van 30 jaar: begint de aftrektermijn opnieuw? Of telt de al verstreken periode mee?`,
  antwoorden:[
   {id:'vbe-015-a1',auteur:'u4',datum:'2025-11-21T14:45:00',rA:{u5:4,u3:4,u1:4},rAdv:{u1:4},body:`De verstreken periode telt mee. De maximale aftrekperiode van 360 maanden geldt per eigenwoningschuld, ook na oversluiten. Een nieuwe looptijd van 30 jaar betekent dus niet dat de aftrek opnieuw 30 jaar loopt.
Ik vermeld de resterende aftrekperiode in het advies en reken de netto lasten na het einde van de aftrek apart door.`},
   {id:'vbe-015-a2',auteur:'u5',datum:'2025-11-21T19:10:00',rA:{u2:4},rAdv:{},body:`En het aflossingsschema moet aansluiten: de lening moet worden afgelost binnen de resterende looptijd van het oorspronkelijke schema om de aftrek te behouden. Controleer dit in het adviespakket.`}
  ]},
 {id:'vbe-016',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-27T15:25:00',views:243,tags:['boeterente','oversluiten','aftrek'],beste:null,
  titel:'Boeterente bij oversluiten: aftrekbaar en meefinancieren?',
  body:`Een klant wil oversluiten naar een lagere rente en moet boeterente betalen. Is die boeterente aftrekbaar? En mag hij die meefinancieren in de nieuwe lening?`,
  antwoorden:[
   {id:'vbe-016-a1',auteur:'u1',datum:'2025-11-30T01:50:00',rA:{u2:4,u7:4},rAdv:{u2:4},body:`Boeterente bij het oversluiten van een eigenwoningschuld is in principe aftrekbaar. Over het meefinancieren bestaan aandachtspunten: controleer de actuele regels en de acceptatie van de geldverstrekker.
Ik zet in het dossier de berekening van het omslagpunt, inclusief het fiscale effect van de boeterente.`},
   {id:'vbe-016-a2',auteur:'u8',datum:'2025-11-30T07:35:00',rA:{u3:5,u1:4,u2:3,u4:4},rAdv:{u3:5,u1:4,u2:3},body:`Belangrijk is dat de klant snapt dat het fiscale voordeel van de boete niet het hele bedrag is. Laat het nettovoordeel van oversluiten zien en leg vast dat je dit hebt toegelicht.`}
  ]},
 {id:'vbe-017',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-30T08:25:00',views:212,tags:['vakantiewoning','box 3','tweede woning'],beste:'vbe-017-a1',
  titel:'Tweede woning of vakantiewoning: renteaftrek?',
  body:`Een klant wil een vakantiewoning kopen en vraagt of de rente aftrekbaar is. Volgens mij niet, maar hoe leg je het beste uit waar die woning dan valt?`,
  antwoorden:[
   {id:'vbe-017-a1',auteur:'u1',datum:'2025-12-01T01:35:00',rA:{u8:4,u4:5,u5:4,u7:3},rAdv:{u4:5,u5:4,u7:3},body:`Klopt, alleen de woning die het hoofdverblijf is kan eigen woning zijn. Een vakantiewoning valt in box 3, en de lening daarvoor is dan een box 3-schuld. Leg dit expliciet vast, ook als de klant zegt het te weten.`},
   {id:'vbe-017-a2',auteur:'u2',datum:'2025-12-02T12:25:00',rA:{u7:5,u5:5},rAdv:{u5:5},body:`Neem de box 3-gevolgen mee in de planning. Bij verhuur van de vakantiewoning gelden aparte aandachtspunten, die bespreek ik standaard met de klant.`}
  ]},
 {id:'vbe-018',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-04T19:45:00',views:428,tags:['familielening','ouders','informatieplicht'],beste:'vbe-018-a1',
  titel:'Familielening voor eigen woning: wat moet de klant regelen?',
  body:`Ouders willen hun kind een lening verstrekken voor de aankoop van een woning. Welke voorwaarden moeten we controleren voor de renteaftrek?`,
  antwoorden:[
   {id:'vbe-018-a1',auteur:'u5',datum:'2025-12-05T06:25:00',rA:{},rAdv:{},body:`Aandachtspunten:
- schriftelijke leningsovereenkomst met een zakelijke rente
- aflossing minimaal annuitair binnen 30 jaar
- de klant moet de gegevens van de lening in de aangifte vermelden (informatieplicht)
- de ouders geven de vordering op in box 3
Leg in het dossier vast hoe de rente is onderbouwd.`},
   {id:'vbe-018-a2',auteur:'u2',datum:'2025-12-06T20:05:00',rA:{u5:5},rAdv:{u5:5},body:`Vergeet de schenkingsrechtelijke kant niet als de ouders de rente of aflossing later kwijtschelden. Dat vraagt om een apart gesprek, eventueel met een notaris.`}
  ]},
 {id:'vbe-019',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-08T07:00:00',views:209,tags:['verhuur','buitenland','overgangsrecht'],beste:null,
  titel:'Woning tijdelijk verhuren tijdens buitenlandse detachering',
  body:`Een klant gaat twee jaar naar het buitenland en wil de woning in die periode verhuren. Wat betekent dat voor de renteaftrek en het overgangsrecht?`,
  antwoorden:[]},
 {id:'vbe-020',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-10T15:35:00',views:343,tags:['scheiding','uitkoop','aflossingseis'],beste:'vbe-020-a1',
  titel:'Uitkoop ex-partner bij scheiding: nieuwe lening eigenwoningschuld?',
  body:`Bij een scheiding koopt de ene partner de andere uit. Is de nieuwe lening voor het overgenomen aandeel eigenwoningschuld? En moet die lening aan de aflossingseis voldoen?`,
  antwoorden:[
   {id:'vbe-020-a1',auteur:'u5',datum:'2025-12-12T01:50:00',rA:{u7:4,u8:5},rAdv:{},body:`De lening voor het verwerven van het aandeel van de ex-partner kan eigenwoningschuld zijn. Voor zover het om nieuwe schuld gaat, geldt de aflossingseis. Heeft de achterblijvende partner zelf overgangsrecht, dan gaat dat alleen over zijn of haar eigen bestaande deel.
Let ook op een eventuele eigenwoningreserve bij de vertrekkende partner, die moet die meenemen naar een volgende woning.`},
   {id:'vbe-020-a2',auteur:'u1',datum:'2025-12-12T09:00:00',rA:{u2:4,u7:4,u3:4},rAdv:{u2:4},body:`Praktisch: vraag het echtscheidingsconvenant op en leg vast welke leningdelen bij wie terechtkomen. Dat is ook voor latere aangiftes belangrijk.`},
   {id:'vbe-020-a3',auteur:'u8',datum:'2025-12-13T07:15:00',rA:{u3:5,u1:4,u7:5,u5:5},rAdv:{u3:5,u1:4,u7:5},body:`Zorg dat beide partijen weten wie welk advies krijgt. Bij een scheiding adviseer je meestal maar een van beiden, leg dat expliciet vast.`}
  ]},
 {id:'vbe-021',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-15T16:05:00',views:465,tags:['scheiding','eigen woning','termijn'],beste:'vbe-021-a1',
  titel:'Vertrokken partner: hoe lang blijft de woning eigen woning?',
  body:`Na een scheiding is een partner vertrokken, de ander woont nog in de woning. Mag de vertrokken partner zijn deel van de rente nog aftrekken?`,
  antwoorden:[
   {id:'vbe-021-a1',auteur:'u4',datum:'2025-12-16T15:45:00',rA:{},rAdv:{},body:`Ja, onder voorwaarden. De woning kan voor de vertrokken partner maximaal twee jaar na vertrek als eigen woning blijven gelden, zolang de ex-partner er blijft wonen. Controleer de actuele voorwaarden voor de situatie van de klant.
Ik noteer de vertrekdatum in het dossier zodat het einde van die termijn bewaakt kan worden.`}
  ]},
 {id:'vbe-022',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-17T07:25:00',views:361,tags:['erfpacht','canon','afkoop'],beste:null,
  titel:'Erfpachtcanon: aftrekbaar als kosten eigen woning?',
  body:`Een klant koopt een woning op erfpachtgrond met een jaarlijkse canon. Is die canon aftrekbaar? En hoe zit het met afkoop van de canon via de hypotheek?`,
  antwoorden:[
   {id:'vbe-022-a1',auteur:'u1',datum:'2025-12-18T05:05:00',rA:{u5:3},rAdv:{u5:3},body:`Periodieke erfpachtcanon is aftrekbaar als kosten van de eigen woning. Bij afkoop ligt het anders: dan wordt het afkoopbedrag onderdeel van de verwervingskosten en kan de lening daarvoor eigenwoningschuld zijn, mits deze aan de aflossingseis voldoet. Controleer altijd de erfpachtvoorwaarden en de acceptatie van de geldverstrekker.`},
   {id:'vbe-022-a2',auteur:'u5',datum:'2025-12-18T21:40:00',rA:{},rAdv:{},body:`Reken beide scenarios netto door. De vergelijking tussen canon en afkoop is erg gevoelig voor de rente en de looptijd van het erfpachtrecht.`}
  ]},
 {id:'vbe-023',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-22T13:35:00',views:595,tags:['KEW','overgangsrecht','vrijstelling'],beste:'vbe-023-a1',
  titel:'Kapitaalverzekering eigen woning: vrijstelling behouden bij oversluiten',
  body:`Een klant heeft een KEW uit 2005 en wil de hypotheek oversluiten naar een andere geldverstrekker. Blijft de vrijstelling behouden als de polis aan de nieuwe lening wordt verpand?`,
  antwoorden:[
   {id:'vbe-023-a1',auteur:'u3',datum:'2025-12-24T09:50:00',rA:{u5:5,u4:4,u2:4},rAdv:{u5:5,u4:4},body:`In principe kan een bestaande KEW onder het overgangsrecht worden voortgezet, ook bij een andere geldverstrekker, mits de polis blijft voldoen aan de voorwaarden. Belangrijk zijn onder andere de minimale premieduur en de bandbreedte van de premies. Verhoging van de premie of het verzekerd kapitaal kan de status raken.
Controleer bij de verzekeraar of zij de polis opnieuw willen verpanden.`},
   {id:'vbe-023-a2',auteur:'u5',datum:'2025-12-25T11:35:00',rA:{u4:4},rAdv:{u4:4},body:`Leg in het dossier de premiehistorie en de polisvoorwaarden vast. Bij een latere uitkering wil je kunnen aantonen dat aan de vrijstellingseisen is voldaan.`}
  ]},
 {id:'vbe-024',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-24T07:15:00',views:305,tags:['extra aflossen','aflossingsschema','annuitair'],beste:'vbe-024-a1',
  titel:'Extra aflossen en het fiscale aflossingsschema',
  body:`Een klant lost extra af op een annuitaire lening. Moet het fiscale aflossingsschema daarna worden aangepast, of mag hij de lagere maandlast hanteren?`,
  antwoorden:[
   {id:'vbe-024-a1',auteur:'u4',datum:'2025-12-25T19:15:00',rA:{u2:3},rAdv:{u2:3},body:`Na een extra aflossing mag het schema worden herrekend op basis van de lagere schuld, binnen de resterende looptijd. De klant hoeft dus niet het oude bedrag te blijven aflossen, maar wel ten minste annuitair over de resterende looptijd. Controleer hoe de geldverstrekker dit verwerkt.`},
   {id:'vbe-024-a2',auteur:'u6',datum:'2025-12-26T16:55:00',rA:{u1:3,u5:3},rAdv:{u1:3,u5:3},body:`In het adviespakket kun je bij het leningdeel de extra aflossing invoeren met datum. Het fiscale schema wordt dan op de resterende looptijd doorgerekend. Kijk na het opslaan even of de looptijd niet onbedoeld is aangepast.`}
  ]},
 {id:'vbe-025',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-28T11:10:00',views:372,tags:['kamerverhuur','eigen woning','vrijstelling'],beste:'vbe-025-a1',
  titel:'Kamerverhuur in eigen woning: gevolgen voor renteaftrek',
  body:`Een klant wil een kamer in de eigen woning verhuren. Heeft dat invloed op de renteaftrek? Ik heb gehoord dat er een vrijstelling is.`,
  antwoorden:[
   {id:'vbe-025-a1',auteur:'u1',datum:'2025-12-30T04:20:00',rA:{u2:3},rAdv:{u2:3},body:`Er bestaat een kamerverhuurvrijstelling voor tijdelijke verhuur van een deel van de eigen woning, onder voorwaarden. Valt de verhuur binnen die regeling, dan blijft de woning in beginsel eigen woning. Bedragen en voorwaarden wisselen, verwijs naar de actuele normen.
Leg vast welke ruimte wordt verhuurd en of er een zelfstandige woonruimte is, want dat maakt verschil.`},
   {id:'vbe-025-a2',auteur:'u8',datum:'2025-12-30T18:05:00',rA:{u7:3,u1:5},rAdv:{u7:3,u1:5},body:`En vraag de klant of de geldverstrekker toestemming geeft voor verhuur. Veel hypotheekvoorwaarden vragen dat.`}
  ]},
 {id:'vbe-026',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-05T10:55:00',views:374,tags:['eigenwoningreserve','bijleenregeling','huurwoning'],beste:'vbe-026-a1',
  titel:'Eigenwoningreserve na verkoop: wanneer vervalt die?',
  body:`Een klant heeft de woning verkocht met overwaarde en gaat eerst een paar jaar huren. Over enkele jaren wil hij weer kopen. Telt de eigenwoningreserve dan nog mee bij de nieuwe financiering?`,
  antwoorden:[
   {id:'vbe-026-a1',auteur:'u5',datum:'2026-01-06T07:40:00',rA:{},rAdv:{},body:`De eigenwoningreserve geldt voor een periode van drie jaar na de verkoop. Koopt de klant binnen die termijn een nieuwe woning, dan moet hij de reserve inbrengen, anders valt dat deel van de nieuwe lening in box 3. Na afloop van de termijn vervalt de reserve en speelt de bijleenregeling voor deze verkoop geen rol meer.
- Leg de verkoopdatum, verkoopprijs, verkoopkosten en de afgeloste eigenwoningschuld vast.
- Noteer de datum waarop de termijn afloopt in het dossier, zodat je dit bij een nieuwe aankoop direct ziet.`},
   {id:'vbe-026-a2',auteur:'u2',datum:'2026-01-06T16:45:00',rA:{u7:3,u8:3,u5:3},rAdv:{u7:3,u8:3},body:`Bespreek ook wat de klant met de vrijgekomen overwaarde doet. Als hij het geld in de tussentijd uitgeeft, moet hij bij een aankoop binnen de termijn toch rekening houden met de reserve. Dat kan een onaangename verrassing geven als de nieuwe lening deels niet aftrekbaar blijkt.`}
  ]},
 {id:'vbe-027',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-08T19:15:00',views:483,tags:['eigenwoningreserve','verkoopkosten','makelaar'],beste:'vbe-027-a1',
  titel:'Verkoopkosten aftrekken bij berekening eigenwoningreserve',
  body:`Bij het berekenen van de eigenwoningreserve: welke verkoopkosten mag ik van de verkoopprijs aftrekken? Denk aan makelaarskosten, energielabel en een boete voor vervroegd aflossen.`,
  antwoorden:[
   {id:'vbe-027-a1',auteur:'u4',datum:'2026-01-09T19:50:00',rA:{u8:3,u5:3,u2:3},rAdv:{u5:3},body:`Je mag de kosten aftrekken die direct verband houden met de verkoop, zoals makelaarscourtage, advertentiekosten en kosten voor een energielabel of bouwkundige keuring die je voor de verkoop laat doen. Een boeterente bij aflossing is geen verkoopkost, maar is onder voorwaarden aftrekbaar als financieringskosten. Vraag de klant om de facturen en bewaar die bij het dossier.`},
   {id:'vbe-027-a2',auteur:'u5',datum:'2026-01-10T10:40:00',rA:{u2:3},rAdv:{u2:3},body:`Kosten voor het opknappen van de woning om hem verkoopklaar te maken worden niet zomaar als verkoopkosten geaccepteerd. Wees daar voorzichtig mee en neem in twijfelgevallen alleen de duidelijke posten mee. Licht in het advies toe welke posten je hebt meegenomen.`}
  ]},
 {id:'vbe-028',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-11T13:10:00',views:323,tags:['overbrugging','aflossingseis','doorstromer'],beste:'vbe-028-a1',
  titel:'Overbruggingslening: geldt de aflossingseis?',
  body:`Een doorstromer koopt eerst en verkoopt later. Er komt een overbruggingslening voor de overwaarde in de oude woning. Moet die lening voldoen aan de aflossingseis om de rente aftrekbaar te houden?`,
  antwoorden:[
   {id:'vbe-028-a1',auteur:'u1',datum:'2026-01-12T00:35:00',rA:{},rAdv:{},body:`Nee, voor een overbruggingslening geldt de aflossingseis niet, mits het om een echte overbrugging gaat van de overwaarde van de oude woning. De rente is in beginsel aftrekbaar als de lening is aangegaan voor de verwerving van de nieuwe eigen woning. Controleer de maximale looptijd die de geldverstrekker hanteert.
- Leg de getaxeerde of verwachte verkoopwaarde en de bestaande schuld vast.
- Noteer de afspraak dat de lening bij verkoop wordt afgelost.`},
   {id:'vbe-028-a2',auteur:'u5',datum:'2026-01-12T05:40:00',rA:{u3:5,u4:4},rAdv:{u3:5},body:`Let wel op de bijleenregeling. Zodra de oude woning verkocht is, ontstaat een eigenwoningreserve en die moet je meenemen in de berekening van de maximale eigenwoningschuld. Maak daarom vooraf een berekening voor het moment van verkoop, zodat de klant weet wat er fiscaal gebeurt.`},
   {id:'vbe-028-a3',auteur:'u2',datum:'2026-01-12T12:40:00',rA:{u4:4,u1:5,u8:5},rAdv:{u8:5},body:`Bespreek ook het scenario dat de verkoop langer duurt of lager uitvalt. De dubbele lasten en de overbruggingsrente kunnen dan flink oplopen. Ik leg in het dossier vast welk scenario ik heb doorgerekend.`}
  ]},
 {id:'vbe-029',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-15T09:35:00',views:328,tags:['leegstand','dubbele lasten','verkoop'],beste:'vbe-029-a1',
  titel:'Leegstaande woning te koop: hoe lang renteaftrek?',
  body:`Een klant is verhuisd en de oude woning staat leeg te koop. Hoe lang blijft de rente op de oude hypotheek aftrekbaar? En geldt dat ook als de woning tijdelijk wordt verhuurd?`,
  antwoorden:[
   {id:'vbe-029-a1',auteur:'u4',datum:'2026-01-16T01:05:00',rA:{u2:5},rAdv:{u2:5},body:`Een leegstaande woning die te koop staat blijft onder voorwaarden nog maximaal drie jaar na het jaar waarin hij leeg kwam te staan eigen woning. Voorwaarde is dat de woning daadwerkelijk leeg staat en te koop wordt aangeboden. Wordt de woning tussentijds verhuurd, dan vervalt die status en valt de woning in box 3.
Leg in het dossier vast sinds wanneer de woning leeg staat en dat hij te koop staat.`},
   {id:'vbe-029-a2',auteur:'u8',datum:'2026-01-16T12:30:00',rA:{u6:3},rAdv:{},body:`Benoem in het adviesrapport ook dat tijdelijke verhuur fiscale gevolgen heeft en dat de geldverstrekker meestal toestemming moet geven. Zo voorkom je dat de klant op eigen houtje verhuurt en later verrast wordt.`}
  ]},
 {id:'vbe-030',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-19T18:50:00',views:150,tags:['verbouwing','leegstand','renteaftrek'],beste:null,
  titel:'Nieuwe woning nog niet betrokken wegens verbouwing',
  body:`Een klant koopt een woning die eerst grondig wordt verbouwd. Hij woont nog een half jaar in zijn huurwoning. Is de rente in die periode aftrekbaar?`,
  antwoorden:[
   {id:'vbe-030-a1',auteur:'u1',datum:'2026-01-19T21:25:00',rA:{},rAdv:{},body:`Ja, in principe wel. Een woning die leeg staat en bestemd is om binnen drie jaar als hoofdverblijf in gebruik te worden genomen, kan al als eigen woning worden aangemerkt. Voorwaarde is dat de woning in die periode niet wordt verhuurd of anderszins gebruikt.
Leg in het dossier de verwachte opleverdatum en de verhuisplanning vast.`},
   {id:'vbe-030-a2',auteur:'u4',datum:'2026-01-20T13:50:00',rA:{},rAdv:{},body:`Vraag ook naar de bouwdepotafspraken. De rente over het bouwdepot wordt verminderd met de rentevergoeding, en alleen het saldo is aftrekbaar. Dat geeft de klant een realistischer beeld van de netto lasten.`}
  ]},
 {id:'vbe-031',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-21T20:20:00',views:573,tags:['box 3','oversluiten','consumptief'],beste:'vbe-031-a1',
  titel:'Bijlenen voor auto bij oversluiten: wat gebeurt er fiscaal?',
  body:`Een klant sluit over en wil tegelijk een bedrag extra lenen voor een auto en een vakantie. Kan dat in de hypotheek en wat betekent dat fiscaal?`,
  antwoorden:[
   {id:'vbe-031-a1',auteur:'u4',datum:'2026-01-22T13:35:00',rA:{u5:4,u2:5},rAdv:{u5:4},body:`Dat kan bij veel geldverstrekkers, maar het extra deel is geen eigenwoningschuld omdat het niet wordt besteed aan de woning. Het valt in box 3 en de rente is niet aftrekbaar. Maak er een apart leningdeel van, zodat de fiscale splitsing helder blijft.
- Controleer de voorwaarden van de geldverstrekker voor bestedingsvrije leningdelen.
- Leg de bestedingsdoelen vast.`},
   {id:'vbe-031-a2',auteur:'u2',datum:'2026-01-22T16:30:00',rA:{u1:5},rAdv:{},body:`Bespreek of dit financieel verstandig is. Een auto over een lange looptijd financieren betekent dat de klant nog rente betaalt als de auto allang weg is. Leg vast dat je dit hebt besproken en wat de klant heeft besloten.`},
   {id:'vbe-031-a3',auteur:'u8',datum:'2026-01-23T11:55:00',rA:{},rAdv:{},body:`Vanuit compliance: neem dit nadrukkelijk mee in de passendheidstoets. Het advies moet aansluiten bij de doelstelling en de risicobereidheid van de klant.`}
  ]},
 {id:'vbe-032',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-24T21:05:00',views:584,tags:['rentemiddeling','boeterente','renteaftrek'],beste:null,
  titel:'Rentemiddeling: is de opslag aftrekbaar?',
  body:`Een klant overweegt rentemiddeling bij de huidige geldverstrekker. De boeterente wordt verwerkt in een opslag op de nieuwe rente. Is die opslag gewoon aftrekbaar als hypotheekrente?`,
  antwoorden:[
   {id:'vbe-032-a1',auteur:'u5',datum:'2026-01-25T05:00:00',rA:{u4:4,u7:3,u8:3},rAdv:{u7:3,u8:3},body:`In de praktijk wordt de rente inclusief de opslag als rente op de eigenwoningschuld behandeld, omdat het onderdeel is van de rente die de klant betaalt. Controleer wel hoe de geldverstrekker dit op de jaaropgave vermeldt. Laat de klant de totale netto kosten vergelijken met oversluiten of met de huidige rente laten doorlopen.
Leg de vergelijking en de uitgangspunten vast in het dossier.`}
  ]},
 {id:'vbe-033',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-29T18:35:00',views:28,tags:['woonboot','eigen woning','hoofdverblijf'],beste:'vbe-033-a1',
  titel:'Woonboot als eigen woning: renteaftrek mogelijk?',
  body:`Een klant wil een woonboot kopen en daar permanent wonen. Kan de lening daarvoor eigenwoningschuld zijn? Waar moet ik op letten?`,
  antwoorden:[
   {id:'vbe-033-a1',auteur:'u1',datum:'2026-01-30T18:15:00',rA:{u7:3,u2:4,u3:4},rAdv:{u7:3,u2:4,u3:4},body:`Ja, een schip of woonwagen dat als hoofdverblijf dient kan voor de inkomstenbelasting als eigen woning gelden. Als de financiering voldoet aan de aflossingseis, kan de rente aftrekbaar zijn. De uitdaging zit meestal in de financiering zelf, omdat niet alle geldverstrekkers woonboten financieren.
- Controleer de voorwaarden van de geldverstrekker over ligplaats en taxatie.
- Leg vast dat de boot het hoofdverblijf wordt.`},
   {id:'vbe-033-a2',auteur:'u3',datum:'2026-01-31T11:05:00',rA:{u2:3,u6:4},rAdv:{u2:3,u6:4},body:`Let ook op de verzekering. Een woonboot vraagt een andere opstal- en casco-dekking dan een gewone woning. Zorg dat die geregeld is voordat de lening ingaat.`}
  ]},
 {id:'vbe-034',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-01T11:30:00',views:53,tags:['box 3','kind','eigen woning'],beste:null,
  titel:'Ouder koopt woning voor studerend kind',
  body:`Ouders willen een appartement kopen in de studiestad van hun kind en daarvoor een hypotheek afsluiten. Het kind gaat er wonen. Is de rente voor de ouders aftrekbaar?`,
  antwoorden:[
   {id:'vbe-034-a1',auteur:'u2',datum:'2026-02-01T18:25:00',rA:{u8:5,u4:5},rAdv:{u8:5},body:`Nee, voor de ouders is dit geen eigen woning, omdat het niet hun hoofdverblijf is. De woning en de lening vallen bij hen in box 3. Bespreek ook of de ouders huur gaan vragen en hoe ze dat vastleggen.
Leg in het dossier vast dat de klant is gewezen op de box 3-gevolgen en op de voorwaarden die geldverstrekkers stellen aan dit soort constructies.`},
   {id:'vbe-034-a2',auteur:'u5',datum:'2026-02-02T18:55:00',rA:{},rAdv:{},body:`Een alternatief is dat het kind zelf koopt en de ouders een lening verstrekken of borg staan. Dan kan het voor het kind wel een eigen woning zijn. Dit vraagt wel goede vastlegging van de familielening en een zakelijke rente.`}
  ]},
 {id:'vbe-035',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-04T10:40:00',views:65,tags:['overlijden','overgangsrecht','langstlevende'],beste:null,
  titel:'Overgangsrecht bij overlijden partner',
  body:`De partner van een klant is overleden. Samen hadden ze een aflossingsvrije lening uit de periode voor 2013. Kan de langstlevende het overgangsrecht van het aandeel van de overleden partner behouden?`,
  antwoorden:[]},
 {id:'vbe-036',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-08T22:20:00',views:253,tags:['restschuld','box 3','verhuizing'],beste:'vbe-036-a1',
  titel:'Restschuld meefinancieren in nieuwe hypotheek',
  body:`Een klant verkoopt met verlies en wil de restschuld meefinancieren in de nieuwe hypotheek. De verkoop vindt dit jaar plaats. Is de rente over het restschulddeel aftrekbaar?`,
  antwoorden:[
   {id:'vbe-036-a1',auteur:'u5',datum:'2026-02-09T21:25:00',rA:{u6:4},rAdv:{u6:4},body:`Nee. Voor restschulden die na 2017 zijn ontstaan geldt geen renteaftrek meer. Het restschulddeel is een box 3-schuld, ook als het in de nieuwe hypotheek wordt meegefinancierd. Maak er een apart leningdeel van, zodat het fiscale onderscheid zichtbaar blijft.
- Controleer of de geldverstrekker restschuldfinanciering toestaat en onder welke voorwaarden.
- Leg de berekening van de restschuld vast.`},
   {id:'vbe-036-a2',auteur:'u2',datum:'2026-02-10T16:45:00',rA:{},rAdv:{},body:`Adviseer de klant om extra aflossingen eerst op het box 3-deel te doen. Dat leningdeel kost netto het meest. Leg vast dat je dit hebt besproken.`}
  ]},
 {id:'vbe-037',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-13T08:35:00',views:587,tags:['restschuld','15 jaar','huren'],beste:'vbe-037-a1',
  titel:'Restschuld uit 2015: aftrek ook zonder nieuwe woning?',
  body:`Een klant heeft in 2015 de woning verkocht met een restschuld en is gaan huren. Hij betaalt die restschuld nog steeds af. Mag hij de rente aftrekken, ook al heeft hij geen eigen woning meer?`,
  antwoorden:[
   {id:'vbe-037-a1',auteur:'u1',datum:'2026-02-13T18:45:00',rA:{},rAdv:{},body:`Ja. Voor restschulden die zijn ontstaan in de periode van eind oktober 2012 tot en met 2017 is de rente maximaal vijftien jaar aftrekbaar. Dat geldt ook als de klant geen nieuwe eigen woning koopt. Voor de restschuld geldt geen aflossingseis.
Leg de verkoopdatum en de hoogte van de restschuld vast, zodat je kunt nagaan tot wanneer de aftrek loopt.`}
  ]},
 {id:'vbe-038',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-16T09:10:00',views:64,tags:['Wet Hillen','eigenwoningforfait','afbouw'],beste:'vbe-038-a1',
  titel:'Afbouw aftrek wegens geen of geringe eigenwoningschuld',
  body:`Een klant heeft bijna geen hypotheek meer en vraagt waarom hij steeds meer belasting betaalt over zijn woning. Hoe leg ik de afbouw van de Wet Hillen kort uit?`,
  antwoorden:[
   {id:'vbe-038-a1',auteur:'u2',datum:'2026-02-16T21:40:00',rA:{},rAdv:{},body:`Als het eigenwoningforfait hoger is dan de aftrekbare kosten, mocht de klant vroeger het verschil volledig aftrekken. Die aftrek wordt sinds 2019 stapsgewijs afgebouwd. Daardoor wordt een steeds groter deel van het positieve saldo belast. De exacte percentages wijzigen per jaar, verwijs naar de actuele normen.
Laat de klant in een berekening zien wat het effect is, en leg vast dat dit geen reden hoeft te zijn om niet af te lossen.`},
   {id:'vbe-038-a2',auteur:'u7',datum:'2026-02-17T00:55:00',rA:{u4:3,u2:4,u3:5,u8:4},rAdv:{u4:3,u2:4,u8:4},body:`Ik zie dit vaak bij gepensioneerden. Het fiscale effect is klein in verhouding tot de rentebesparing van aflossen. Benoem dat expliciet, want klanten denken soms dat ze juist een hypotheek moeten aanhouden.`}
  ]},
 {id:'vbe-039',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-20T13:10:00',views:280,tags:['eigenwoningforfait','WOZ','villa'],beste:null,
  titel:'Eigenwoningforfait bij woning met hoge WOZ-waarde',
  body:`Een klant heeft een woning met een hoge WOZ-waarde. Klopt het dat boven een bepaalde grens een hoger forfaitpercentage geldt? Hoe neem ik dit mee in de netto lasten?`,
  antwoorden:[
   {id:'vbe-039-a1',auteur:'u5',datum:'2026-02-21T02:20:00',rA:{u8:3,u3:4},rAdv:{u3:4},body:`Klopt. Boven een bepaalde WOZ-grens geldt een hoger percentage over het meerdere. Zowel de grens als de percentages worden jaarlijks vastgesteld, gebruik dus de actuele normen. In de netto lastenberekening neem ik het forfait apart op, zodat de klant ziet wat het effect is.
Leg de gebruikte WOZ-waarde en het belastingjaar vast in het dossier.`},
   {id:'vbe-039-a2',auteur:'u6',datum:'2026-02-22T01:25:00',rA:{u7:5,u2:4},rAdv:{u7:5},body:`In het adviespakket wordt het forfait automatisch berekend op basis van de ingevoerde WOZ-waarde. Controleer wel of de WOZ-waarde actueel is, want vaak staat er nog de koopsom of een oude waarde.`}
  ]},
 {id:'vbe-040',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-21T21:50:00',views:43,tags:['overgangsrecht','verhogen','aflossingsvrij'],beste:'vbe-040-a1',
  titel:'Aflossingsvrij leningdeel verhogen onder overgangsrecht',
  body:`Een klant heeft een aflossingsvrije lening onder het overgangsrecht en wil die verhogen voor een verbouwing. Kan het extra bedrag ook aflossingsvrij en aftrekbaar zijn?`,
  antwoorden:[
   {id:'vbe-040-a1',auteur:'u4',datum:'2026-02-22T00:05:00',rA:{},rAdv:{},body:`Nee. Het overgangsrecht geldt alleen voor de bestaande eigenwoningschuld op het peilmoment. Een verhoging voor verbouwing is een nieuwe eigenwoningschuld die aan de aflossingseis moet voldoen. Je kunt het bestaande deel aflossingsvrij laten en het extra bedrag in een nieuw annuitair of lineair leningdeel onderbrengen.
Leg vast welk deel onder het overgangsrecht valt en welk deel nieuw is.`},
   {id:'vbe-040-a2',auteur:'u5',datum:'2026-02-22T10:50:00',rA:{u8:3},rAdv:{u8:3},body:`Let erop dat het aflossingsvrije deel niet onbedoeld wordt aangepast bij het splitsen. Bij sommige geldverstrekkers moet je dit expliciet aangeven.`}
  ]},
 {id:'vbe-041',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-26T11:10:00',views:431,tags:['vooruitbetaalde rente','renteaftrek','aangifte'],beste:null,
  titel:'Vooruitbetaalde rente: aftrekbaar in het jaar van betaling?',
  body:`Een klant wil aan het eind van het jaar rente vooruitbetalen om nog dit jaar aftrek te krijgen. Is dat toegestaan?`,
  antwoorden:[
   {id:'vbe-041-a1',auteur:'u5',datum:'2026-02-27T02:55:00',rA:{u6:4,u3:3,u4:3,u2:3},rAdv:{u3:3,u2:3},body:`Er gelden beperkingen voor vooruitbetaalde rente. Alleen rente die betrekking heeft op een beperkte periode na het jaar van betaling is aftrekbaar in het jaar van betaling, de rest wordt toegerekend aan latere jaren. Controleer de actuele regels voordat je dit adviseert.
Bovendien moet de geldverstrekker vooruitbetaling toestaan. Leg vast wat je hebt gecontroleerd en adviseer de klant dit in de aangifte goed te verantwoorden.`}
  ]},
 {id:'vbe-042',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-02T13:20:00',views:288,tags:['financieringskosten','aftrekbaar','aankoop'],beste:'vbe-042-a1',
  titel:'Financieringskosten die wel en niet aftrekbaar zijn',
  body:`Ik wil starters een helder overzicht geven van welke kosten bij aankoop aftrekbaar zijn. Welke posten nemen jullie standaard op?`,
  antwoorden:[
   {id:'vbe-042-a1',auteur:'u1',datum:'2026-03-02T22:25:00',rA:{},rAdv:{},body:`Aftrekbaar zijn in de regel de kosten die je maakt om de lening te krijgen:
- advieskosten en bemiddelingskosten voor de hypotheek
- taxatiekosten
- notariskosten voor de hypotheekakte
- afsluitprovisie en kosten voor NHG
Niet aftrekbaar zijn kosten die bij de aankoop van de woning horen, zoals overdrachtsbelasting, notariskosten voor de leveringsakte en de aankoopmakelaar.`},
   {id:'vbe-042-a2',auteur:'u5',datum:'2026-03-03T03:40:00',rA:{u1:5,u7:5},rAdv:{u1:5},body:`Let op dat de aftrekbare financieringskosten alleen aftrekbaar zijn in het jaar waarin ze zijn betaald. Maak voor de klant een overzicht dat hij bij zijn aangifte kan gebruiken, en bewaar de nota van afrekening in het dossier.`}
  ]},
 {id:'vbe-043',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-04T12:20:00',views:266,tags:['hoofdverblijf','tweede woning','eigen woning'],beste:null,
  titel:'Twee woningen tegelijk: welke is de eigen woning?',
  body:`Een klant heeft een appartement in de stad en een huis buiten waar hij in het weekend woont. Hij wil voor beide renteaftrek. Kan dat?`,
  antwoorden:[
   {id:'vbe-043-a1',auteur:'u4',datum:'2026-03-05T11:25:00',rA:{u5:5,u1:4,u8:3,u3:4},rAdv:{u8:3},body:`Nee, er kan maar een woning tegelijk de eigen woning zijn, namelijk het hoofdverblijf. Uitzonderingen zijn tijdelijk, zoals bij verhuizing of leegstand. De tweede woning valt in box 3.
Leg vast welke woning het hoofdverblijf is en waar de klant staat ingeschreven, maar besef dat de feitelijke situatie bepalend is.`},
   {id:'vbe-043-a2',auteur:'u2',datum:'2026-03-06T00:20:00',rA:{u1:3,u5:5,u4:4},rAdv:{u4:4},body:`Bespreek ook welke lening je aan welke woning koppelt. Het is fiscaal gunstig als de financiering op de eigen woning zit, maar alleen als het geld daar ook voor is gebruikt. Herfinancieren om fiscaal voordeel te halen werkt niet.`}
  ]},
 {id:'vbe-044',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-08T08:50:00',views:418,tags:['overgangsrecht','oversluiten','aflossingsvrij'],beste:'vbe-044-a1',
  titel:'Aflossingsvrij oversluiten bij andere geldverstrekker',
  body:`Een klant heeft een aflossingsvrije lening uit 2010 en wil oversluiten vanwege een lagere rente. Verliest hij het overgangsrecht als hij naar een andere geldverstrekker gaat?`,
  antwoorden:[
   {id:'vbe-044-a1',auteur:'u5',datum:'2026-03-09T03:55:00',rA:{u8:5,u2:5},rAdv:{u2:5},body:`Nee, het overgangsrecht is gekoppeld aan de klant en de schuld, niet aan de geldverstrekker. Bij oversluiten tot maximaal het bedrag van de bestaande eigenwoningschuld behoudt hij de fiscale status. De resterende aftrekperiode loopt gewoon door.
- Controleer of de nieuwe geldverstrekker aflossingsvrij toestaat binnen de eigen acceptatienormen.
- Leg de hoogte van de oude schuld en het overgangsrechtbedrag vast.`},
   {id:'vbe-044-a2',auteur:'u1',datum:'2026-03-10T01:55:00',rA:{u8:3},rAdv:{u8:3},body:`Vraag de oude jaaropgaven op. Daarmee kun je de fiscale historie onderbouwen als er later vragen komen.`}
  ]},
 {id:'vbe-045',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-12T12:45:00',views:324,tags:['onderhoud','bijlenen','eigenwoningschuld'],beste:null,
  titel:'Kosten van onderhoud financieren: eigenwoningschuld?',
  body:`Een klant wil bijlenen om een nieuw dak te laten leggen en de kozijnen te schilderen. Is dat eigenwoningschuld, of alleen als het een verbetering is?`,
  antwoorden:[]},
 {id:'vbe-046',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-15T07:20:00',views:214,tags:['voorlopige aanslag','teruggaaf','starter'],beste:'vbe-046-a1',
  titel:'Hypotheekrente teruggaaf via voorlopige aanslag',
  body:`Een starter vraagt hoe hij de renteaftrek maandelijks terugkrijgt. Moet ik daar in mijn advies iets over zeggen of is dat aan de klant?`,
  antwoorden:[
   {id:'vbe-046-a1',auteur:'u1',datum:'2026-03-15T13:05:00',rA:{u4:5,u6:5,u5:5,u3:5},rAdv:{u6:5,u5:5,u3:5},body:`Ik leg het altijd uit, want het heeft direct effect op de netto maandlast. De klant kan bij de Belastingdienst een voorlopige aanslag aanvragen, zodat de teruggaaf maandelijks wordt uitbetaald. Doet hij dat niet, dan krijgt hij het geld pas na de aangifte.
Leg in het dossier vast dat je dit hebt besproken.`},
   {id:'vbe-046-a2',auteur:'u8',datum:'2026-03-16T07:15:00',rA:{u2:3,u6:3,u1:3},rAdv:{u2:3},body:`Wees duidelijk dat de klant zelf verantwoordelijk is voor de aanvraag en dat de bedragen een schatting zijn. Een disclaimer in het adviesrapport helpt hierbij.`},
   {id:'vbe-046-a3',auteur:'u4',datum:'2026-03-16T14:05:00',rA:{u5:4,u2:3,u3:5},rAdv:{u5:4,u2:3},body:`Wijs de klant erop dat hij de voorlopige aanslag moet aanpassen als de situatie wijzigt, bijvoorbeeld na oversluiten of een renteherziening. Anders kan hij achteraf moeten terugbetalen.`}
  ]},
 {id:'vbe-047',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-18T16:20:00',views:500,tags:['spaarhypotheek','KEW','bandbreedte'],beste:null,
  titel:'Bandbreedte bij spaarhypotheek onder overgangsrecht',
  body:`Een klant heeft een spaarhypotheek met een KEW uit 2008. Hij wil de premie verlagen omdat zijn inkomen daalt. Wat zijn de fiscale risicos?`,
  antwoorden:[
   {id:'vbe-047-a1',auteur:'u3',datum:'2026-03-19T16:15:00',rA:{},rAdv:{},body:`Voor de vrijstelling van een KEW gelden eisen aan de premiebetaling, waaronder een bandbreedte tussen de hoogste en laagste premie en een minimale looptijd. Een verlaging kan gevolgen hebben als die buiten de bandbreedte valt. Controleer de polisvoorwaarden en vraag de verzekeraar om een berekening.
Leg de premiehistorie en de wijziging vast.`},
   {id:'vbe-047-a2',auteur:'u5',datum:'2026-03-20T03:55:00',rA:{u3:4},rAdv:{},body:`Bekijk ook de alternatieven, zoals een deel van de lening omzetten in een annuitair deel. Laat de klant alle scenarios zien voordat hij kiest.`}
  ]},
 {id:'vbe-048',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-22T10:35:00',views:54,tags:['familielening','starter','aflossingseis'],beste:'vbe-048-a1',
  titel:'Starter met lening van ouders en hypotheek',
  body:`Ouders lenen hun kind een bedrag voor de aankoop van een woning, naast een hypotheek bij een geldverstrekker. Moet de onderhandse lening ook aan de aflossingseis voldoen voor renteaftrek?`,
  antwoorden:[
   {id:'vbe-048-a1',auteur:'u5',datum:'2026-03-23T06:25:00',rA:{u4:3,u8:5,u3:5,u1:5},rAdv:{u8:5,u3:5,u1:5},body:`Ja, een familielening die na 2012 is afgesloten moet ook voldoen aan de aflossingseis om eigenwoningschuld te zijn. Leg de lening schriftelijk vast met een aflossingsschema en een zakelijke rente. De klant moet de lening ook in zijn aangifte opgeven.
- Controleer of de rente zakelijk is.
- Leg het aflossingsschema vast.`},
   {id:'vbe-048-a2',auteur:'u2',datum:'2026-03-23T22:20:00',rA:{u1:5},rAdv:{},body:`Bespreek ook de positie van de ouders: zij moeten de vordering in box 3 opgeven. En vraag of de geldverstrekker de familielening meeneemt in de toetsing.`}
  ]},
 {id:'vbe-049',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-27T11:50:00',views:251,tags:['praktijkruimte','ondernemer','eigen woning'],beste:null,
  titel:'Woning gedeeltelijk gebruikt als praktijkruimte',
  body:`Een zelfstandige gebruikt een deel van zijn woning als praktijkruimte met eigen ingang. Heeft dat invloed op de renteaftrek?`,
  antwoorden:[]},
 {id:'vbe-050',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-29T08:10:00',views:87,tags:['verbouwing','herfinanciering','eigen geld'],beste:'vbe-050-a1',
  titel:'Herfinancieren verbouwing achteraf: eigenwoningschuld?',
  body:`Een klant heeft vorig jaar een verbouwing met eigen spaargeld betaald. Nu wil hij dat bedrag bijlenen. Is die nieuwe lening eigenwoningschuld?`,
  antwoorden:[
   {id:'vbe-050-a1',auteur:'u4',datum:'2026-03-30T02:05:00',rA:{u1:4,u8:3,u5:4},rAdv:{u5:4},body:`In de regel niet. Eigenwoningschuld moet zijn aangegaan voor de verwerving, verbetering of onderhoud van de eigen woning. Als de verbouwing al met eigen geld is betaald, wordt de nieuwe lening niet meer voor de woning besteed maar vult zij het spaargeld aan. Dat deel valt dan in box 3.
Leg de feiten vast en bespreek dit uitdrukkelijk met de klant.`},
   {id:'vbe-050-a2',auteur:'u5',datum:'2026-03-31T01:10:00',rA:{u1:3},rAdv:{u1:3},body:`Er zijn situaties waarin de timing net anders ligt, bijvoorbeeld bij een lening die al vooraf was aangevraagd. Bekijk het per geval en laat bij twijfel een fiscalist meekijken.`}
  ]},
 {id:'vbe-051',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-04T07:00:00',views:116,tags:['30 jaar','overgangsrecht','einde aftrek'],beste:'vbe-051-a1',
  titel:'Einde aftrekperiode voor leningen van voor 2001',
  body:`Een klant heeft een lening die al bestond op 1 januari 2001. Hij vraagt tot wanneer hij nog renteaftrek heeft. Wat moet ik hem vertellen en wat betekent dat voor zijn netto lasten?`,
  antwoorden:[
   {id:'vbe-051-a1',auteur:'u5',datum:'2026-04-04T13:30:00',rA:{u1:5,u8:4,u7:5},rAdv:{u1:5},body:`Voor leningen die op 1 januari 2001 al bestonden, is de dertigjarige aftrekperiode op die datum gaan lopen. De aftrek eindigt daarmee na 2030. Vanaf dat moment stijgen de netto lasten, terwijl de bruto rente gelijk blijft.
- Maak een netto lastenoverzicht voor en na het einde van de aftrek.
- Bespreek of extra aflossen of een andere verdeling van de lening zinvol is.
Leg de ingangsdatum van de aftrekperiode vast in het dossier.`},
   {id:'vbe-051-a2',auteur:'u2',datum:'2026-04-05T12:20:00',rA:{u8:3,u5:4,u7:5},rAdv:{u5:4},body:`Neem dit mee in de financiele planning, zeker als de klant rond die tijd ook met pensioen gaat. Twee inkomenseffecten tegelijk kunnen de betaalbaarheid flink raken.`}
  ]},
 {id:'vbe-052',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-06T07:20:00',views:268,tags:['tarief','renteaftrek','netto lasten'],beste:'vbe-052-a1',
  titel:'Aftrek tegen maximaal tarief: hoe toelichten?',
  body:`Klanten met een hoger inkomen verwachten soms aftrek tegen hun toptarief. Hoe leggen jullie de beperking van het aftrektarief uit zonder in percentages te verdwalen?`,
  antwoorden:[
   {id:'vbe-052-a1',auteur:'u1',datum:'2026-04-06T18:25:00',rA:{u6:4,u7:4},rAdv:{u6:4},body:`Ik leg uit dat de aftrek van hypotheekrente is beperkt tot een maximaal tarief, ook als het inkomen in een hogere schijf valt. Het exacte percentage wijzigt, dus ik verwijs naar de actuele normen en laat het effect zien in de netto lastenberekening. Dat is voor de klant duidelijker dan een losse uitleg.
Leg vast dat de netto lasten zijn berekend volgens de regels van het lopende jaar.`},
   {id:'vbe-052-a2',auteur:'u8',datum:'2026-04-07T16:55:00',rA:{},rAdv:{},body:`Neem in het rapport op dat fiscale regels kunnen wijzigen en dat de netto lasten daarmee kunnen veranderen. Dat beschermt zowel de klant als het kantoor.`}
  ]},
 {id:'vbe-053',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-11T19:30:00',views:201,tags:['bijleenregeling','eigenwoningreserve','box 3'],beste:'vbe-053-a1',
  titel:'Bijleenregeling bij verhuizing naar goedkopere woning',
  body:`Een klant verkoopt een woning met veel overwaarde en koopt een goedkopere woning. Hij wil toch een hypotheek nemen en het spaargeld houden. Wat is dan fiscaal de situatie?`,
  antwoorden:[
   {id:'vbe-053-a1',auteur:'u5',datum:'2026-04-12T12:30:00',rA:{u8:5},rAdv:{},body:`Door de bijleenregeling moet de eigenwoningreserve in mindering worden gebracht op de kosten van de nieuwe woning. Als de reserve groter is dan de aankoopkosten, is er geen ruimte voor eigenwoningschuld. Een hypotheek die de klant dan toch afsluit, valt in box 3 en de rente is niet aftrekbaar.
Leg de berekening vast en bespreek of een hypotheek in box 3 voor deze klant zinvol is.`},
   {id:'vbe-053-a2',auteur:'u2',datum:'2026-04-13T10:55:00',rA:{u7:4,u4:4,u6:5,u1:4},rAdv:{u4:4,u1:4},body:`Soms heeft de klant een goede reden voor box 3-financiering, bijvoorbeeld liquiditeit. Maar het moet een bewuste keuze zijn. Leg de afweging vast.`}
  ]},
 {id:'vbe-054',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-14T11:45:00',views:228,tags:['eigenwoningreserve','verbouwing','bijleenregeling'],beste:null,
  titel:'Eigenwoningreserve verminderen met verbouwingskosten',
  body:`Een klant heeft een eigenwoningreserve en koopt een nieuwe woning die hij wil verbouwen. Tellen de verbouwingskosten mee bij de berekening van de maximale eigenwoningschuld?`,
  antwoorden:[
   {id:'vbe-054-a1',auteur:'u4',datum:'2026-04-14T15:05:00',rA:{},rAdv:{},body:`Ja, kosten voor verbetering van de nieuwe woning tellen in de regel mee bij de verwervingskosten, waardoor er meer ruimte is voor eigenwoningschuld naast de reserve. Belangrijk is dat de verbouwing daadwerkelijk wordt uitgevoerd en kan worden onderbouwd.
- Vraag een offerte of bouwbegroting op.
- Leg de verdeling van eigen geld en lening vast.`},
   {id:'vbe-054-a2',auteur:'u5',datum:'2026-04-15T10:20:00',rA:{u3:4,u8:5},rAdv:{},body:`Let op de timing. Gebeurt de verbouwing pas veel later, dan wordt het lastiger. Controleer de actuele regels en laat bij twijfel een fiscalist meekijken.`}
  ]},
 {id:'vbe-055',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-18T12:15:00',views:44,tags:['samenwonen','fiscaal partner','verdeling'],beste:'vbe-055-a1',
  titel:'Renteaftrek bij samenwonen zonder fiscaal partnerschap',
  body:`Twee samenwoners kopen samen een woning, ieder voor de helft eigenaar. Ze zijn geen fiscaal partner. Hoe wordt de renteaftrek verdeeld?`,
  antwoorden:[
   {id:'vbe-055-a1',auteur:'u2',datum:'2026-04-18T16:15:00',rA:{u1:4,u3:5},rAdv:{u3:5},body:`Zonder fiscaal partnerschap kan ieder alleen de rente aftrekken over zijn eigen deel van de eigenwoningschuld, in verhouding tot het eigendom. Ook het eigenwoningforfait wordt naar die verhouding verdeeld. Vrij schuiven zoals bij fiscale partners is niet mogelijk.
Leg de eigendomsverhouding en de verdeling van de schuld vast.`},
   {id:'vbe-055-a2',auteur:'u1',datum:'2026-04-18T21:50:00',rA:{u4:4,u6:3,u3:4},rAdv:{u6:3,u3:4},body:`Wijs de klanten ook op een samenlevingscontract met afspraken over de woning. Dat staat los van de fiscale regels, maar is bij een breuk erg belangrijk.`}
  ]},
 {id:'vbe-056',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-21T19:15:00',views:533,tags:['eigendom','hoofdelijk','fiscaal partner'],beste:null,
  titel:'Woning op naam van een partner, beide hoofdelijk aansprakelijk',
  body:`Bij gehuwde klanten staat de woning op naam van een van beiden, maar ze zijn allebei hoofdelijk aansprakelijk. Maakt dat uit voor de renteaftrek?`,
  antwoorden:[]},
 {id:'vbe-057',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-26T20:25:00',views:578,tags:['pensioen','bedrag ineens','aflossen'],beste:'vbe-057-a1',
  titel:'Aflossen met bedrag ineens uit pensioen',
  body:`Een klant gaat met pensioen en overweegt een bedrag ineens op te nemen om de hypotheek af te lossen. Wat zijn de fiscale aandachtspunten voor de eigen woning?`,
  antwoorden:[
   {id:'vbe-057-a1',auteur:'u7',datum:'2026-04-26T23:00:00',rA:{},rAdv:{},body:`Een bedrag ineens is belast in box 1 in het jaar van opname, dus het netto bedrag is lager dan het bruto bedrag. Daarna kan aflossen de rentelast verlagen, maar ook de renteaftrek. Controleer de actuele regels en laat het effect op de uitkering en toeslagen zien.
Leg vast welke scenarios je hebt doorgerekend.`},
   {id:'vbe-057-a2',auteur:'u2',datum:'2026-04-27T15:20:00',rA:{},rAdv:{},body:`Kijk ook naar het effect van de Wet Hillen. Als de schuld bijna afgelost is, verandert het fiscale saldo van de woning. Meestal is aflossen netto toch voordelig, maar laat het rekenen.`},
   {id:'vbe-057-a3',auteur:'u5',datum:'2026-04-28T01:10:00',rA:{},rAdv:{},body:`Bespreek of de klant voldoende buffer overhoudt. Een afgeloste woning maakt de klant minder flexibel als er later geld nodig is.`}
  ]},
 {id:'vbe-058',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-29T21:10:00',views:447,tags:['bouwdepot','box 3','verbouwing'],beste:null,
  titel:'Bouwdepot niet volledig gebruikt: wat met het restant?',
  body:`Een klant heeft het bouwdepot niet helemaal opgemaakt. Het restant wordt na de looptijd verrekend. Wat betekent dat fiscaal als het restant niet wordt afgelost?`,
  antwoorden:[
   {id:'vbe-058-a1',auteur:'u4',datum:'2026-04-30T19:25:00',rA:{u7:4,u6:3,u5:5},rAdv:{u7:4,u6:3},body:`Het niet gebruikte deel is niet besteed aan de woning en is daarmee geen eigenwoningschuld. Meestal wordt het restant na afloop met de lening verrekend, waardoor het probleem verdwijnt. Wordt het uitbetaald aan de klant, dan valt dat deel in box 3.
Controleer de voorwaarden van de geldverstrekker voor afloop van het bouwdepot.`},
   {id:'vbe-058-a2',auteur:'u6',datum:'2026-05-01T19:40:00',rA:{u5:3,u8:4,u1:5},rAdv:{u5:3,u1:5},body:`Werk na afloop het leningdeel in het adviespakket bij. Ik zie geregeld dossiers waar het oorspronkelijke bedrag blijft staan, waardoor de netto lasten in latere adviezen niet kloppen.`}
  ]},
 {id:'vbe-059',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-04T10:25:00',views:112,tags:['emigratie','buitenland','renteaftrek'],beste:'vbe-059-a1',
  titel:'Eigen woning in het buitenland na emigratie',
  body:`Een klant emigreert en houdt zijn Nederlandse woning aan, die hij gaat verhuren. Wat gebeurt er met de renteaftrek?`,
  antwoorden:[
   {id:'vbe-059-a1',auteur:'u5',datum:'2026-05-04T19:05:00',rA:{u2:3},rAdv:{},body:`Na vertrek is de woning niet langer zijn hoofdverblijf en dus geen eigen woning meer. Bij verhuur vervalt de status direct. Voor buitenlandse belastingplichtigen gelden aparte regels, ook voor de belastingheffing over de woning.
Adviseer de klant een fiscalist met internationale kennis in te schakelen en leg vast dat je dit hebt geadviseerd.`}
  ]},
 {id:'vbe-060',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-06T17:40:00',views:382,tags:['zelfbouw','bouwkavel','renteaftrek'],beste:'vbe-060-a1',
  titel:'Hypotheek voor aankoop grond voor zelfbouw',
  body:`Een klant koopt een bouwkavel en laat daar een woning op bouwen. De bouw start pas over een jaar. Is de rente over de lening voor de grond al aftrekbaar?`,
  antwoorden:[
   {id:'vbe-060-a1',auteur:'u1',datum:'2026-05-07T00:40:00',rA:{u7:4,u6:5,u4:3,u3:5},rAdv:{u6:5,u4:3,u3:5},body:`De lening kan eigenwoningschuld zijn als de woning bestemd is om binnen drie jaar als hoofdverblijf te worden gebruikt. De termijn is dus belangrijk: als de bouw uitloopt, kan de aftrek in gevaar komen. Leg de planning en de bouwvergunning vast in het dossier.
Controleer ook de voorwaarden van de geldverstrekker voor kavelfinanciering.`},
   {id:'vbe-060-a2',auteur:'u4',datum:'2026-05-07T15:50:00',rA:{},rAdv:{},body:`Bespreek met de klant wat er gebeurt als de bouw vertraagt. Een realistische planning en een buffer voor dubbele lasten zijn verstandig.`}
  ]},
 {id:'vbe-061',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-11T12:00:00',views:421,tags:['betalingspauze','aflossingseis','achterstand'],beste:null,
  titel:'Aflossingsachterstand na betalingspauze',
  body:`Een klant heeft door ziekte een paar maanden niet afgelost met toestemming van de geldverstrekker. Verliest hij daardoor de renteaftrek?`,
  antwoorden:[
   {id:'vbe-061-a1',auteur:'u5',datum:'2026-05-12T08:45:00',rA:{u2:3},rAdv:{u2:3},body:`Er is een regeling voor achterstanden in de aflossing. Een achterstand leidt niet direct tot verlies van de aftrek, maar moet binnen een bepaalde termijn worden ingehaald. Gebeurt dat niet, dan kan de fiscale status van een deel van de lening veranderen. Controleer de actuele regels.
Leg vast welke afspraak met de geldverstrekker is gemaakt en hoe de achterstand wordt ingehaald.`},
   {id:'vbe-061-a2',auteur:'u3',datum:'2026-05-13T01:35:00',rA:{u6:4,u2:3},rAdv:{u6:4},body:`Kijk ook of de klant een woonlastenverzekering heeft. Een uitkering kan helpen de aflossing bij te houden.`}
  ]},
 {id:'vbe-062',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-15T10:30:00',views:294,tags:['dossier','compliance','fiscaal'],beste:'vbe-062-a1',
  titel:'Vastleggen fiscale toelichting in adviesrapport',
  body:`Hoe uitgebreid moet de fiscale toelichting in het adviesrapport zijn? Ik twijfel tussen een korte samenvatting en een volledige uitleg.`,
  antwoorden:[
   {id:'vbe-062-a1',auteur:'u8',datum:'2026-05-16T05:35:00',rA:{u6:4,u3:3,u2:4,u4:3},rAdv:{u6:4,u4:3},body:`Het rapport moet de klant in staat stellen het advies te begrijpen. Ik adviseer:
- de fiscale status per leningdeel benoemen
- de uitgangspunten van de netto lastenberekening vermelden
- aangeven dat fiscale regels kunnen wijzigen
Een uitgebreide juridische uitleg is niet nodig, maar de keuzes moeten wel herleidbaar zijn.`},
   {id:'vbe-062-a2',auteur:'u5',datum:'2026-05-17T05:45:00',rA:{},rAdv:{},body:`Ik voeg altijd een berekening van de eigenwoningreserve en het overgangsrecht toe als bijlage. Dat scheelt veel vragen bij latere adviezen.`}
  ]},
 {id:'vbe-063',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-18T15:10:00',views:193,tags:['adviespakket','overgangsrecht','leningdeel'],beste:'vbe-063-a1',
  titel:'Overgangsrecht registreren in het adviespakket',
  body:`Hoe registreer ik in het adviespakket welk deel van een lening onder het overgangsrecht valt? Ik zie het niet terug in de netto lasten.`,
  antwoorden:[
   {id:'vbe-063-a1',auteur:'u6',datum:'2026-05-19T07:35:00',rA:{},rAdv:{},body:`Het overgangsrecht stel je per leningdeel in bij de fiscale gegevens. Vul daar het bedrag en de ingangsdatum van de aftrekperiode in. De netto lastenberekening gebruikt die gegevens om de looptijd van de aftrek te bepalen.
Werkt het niet, controleer dan of het leningdeel als box 1 is gemarkeerd. Dat gaat geregeld mis bij geimporteerde dossiers.`},
   {id:'vbe-063-a2',auteur:'u1',datum:'2026-05-20T01:45:00',rA:{u2:4,u5:4,u7:3},rAdv:{u2:4,u5:4,u7:3},body:`Ik check daarnaast altijd de afsluitdatum van de lening. Een verkeerde datum geeft een verkeerde einddatum van de aftrek.`}
  ]},
 {id:'vbe-064',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-21T11:15:00',views:197,tags:['verbouwing','eigen geld','termijn'],beste:null,
  titel:'Verbouwen met lening na aankoop binnen zes maanden',
  body:`Een klant heeft de woning grotendeels met eigen geld gekocht en wil een paar maanden later alsnog een hypotheek afsluiten. Kan dat nog eigenwoningschuld zijn?`,
  antwoorden:[]},
 {id:'vbe-065',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-27T08:25:00',views:311,tags:['restschuld','aflossing','box 3'],beste:null,
  titel:'Restschuld afbetalen naast nieuwe eigenwoningschuld',
  body:`Een klant heeft een box 3-restschuld en een nieuwe hypotheek. Hij wil extra aflossen. Moet hij eerst de restschuld aflossen?`,
  antwoorden:[
   {id:'vbe-065-a1',auteur:'u2',datum:'2026-05-28T04:55:00',rA:{u4:5,u3:3,u8:4},rAdv:{u4:5,u8:4},body:`In de meeste gevallen is het netto voordeliger om eerst de restschuld af te lossen, omdat de rente daarop niet aftrekbaar is. Controleer wel de voorwaarden van de geldverstrekker voor boetevrij aflossen en of er een minimale looptijd voor de restschuld geldt.
Leg vast welke aflossingsvolgorde je hebt geadviseerd en waarom.`},
   {id:'vbe-065-a2',auteur:'u5',datum:'2026-05-28T18:50:00',rA:{u6:3,u7:5},rAdv:{u7:5},body:`Kijk ook naar de schuldendrempel in box 3. Een kleine restschuld kan daardoor nauwelijks effect hebben in box 3. De drempel wijzigt, verwijs naar de actuele normen.`}
  ]},
 {id:'vbe-066',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-29T09:55:00',views:262,tags:['scheiding','overgangsrecht','uitkoop'],beste:'vbe-066-a1',
  titel:'Aflossingsvrij deel bij uitkoop ex-partner',
  body:`Bij een scheiding neemt de ene partner de woning over. Er is een aflossingsvrij deel onder het overgangsrecht. Mag dat volledig aflossingsvrij blijven bij de partner die blijft?`,
  antwoorden:[
   {id:'vbe-066-a1',auteur:'u5',datum:'2026-05-29T13:05:00',rA:{u2:5,u8:3,u4:5,u1:5},rAdv:{u2:5,u8:3,u4:5,u1:5},body:`Dit is een gevoelig onderwerp. De partner die blijft, behoudt in beginsel het overgangsrecht voor zijn eigen deel van de bestaande schuld. Voor het aandeel van de ex-partner zijn er specifieke regels. Controleer de actuele regels en laat het bij twijfel bevestigen door een fiscalist.
Leg de verdeling van de schuld en de fiscale status vast.`},
   {id:'vbe-066-a2',auteur:'u8',datum:'2026-05-29T17:40:00',rA:{},rAdv:{},body:`Neem in het rapport op dat de fiscale gevolgen afhankelijk zijn van de definitieve afspraken in het echtscheidingsconvenant. Adviseer de klant om dit af te stemmen met de mediator of advocaat.`}
  ]},
 {id:'vbe-067',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-02T08:15:00',views:325,tags:['erfpacht','afkoop','eigenwoningschuld'],beste:'vbe-067-a1',
  titel:'Erfpacht afkopen en financieren: eigenwoningschuld?',
  body:`Een klant wil de erfpacht eeuwigdurend afkopen en dat bedrag bijlenen. Is die lening eigenwoningschuld?`,
  antwoorden:[
   {id:'vbe-067-a1',auteur:'u4',datum:'2026-06-02T23:10:00',rA:{u1:4},rAdv:{u1:4},body:`Een lening voor de afkoop van erfpacht kan eigenwoningschuld zijn, omdat het gaat om de verwerving van een recht op de eigen woning. De lening moet wel voldoen aan de aflossingseis. Leg de afkoopsom en de akte vast.
Controleer de voorwaarden van de geldverstrekker over de waardering van de woning na afkoop.`},
   {id:'vbe-067-a2',auteur:'u2',datum:'2026-06-03T16:15:00',rA:{},rAdv:{},body:`Maak een vergelijking tussen de canon blijven betalen en afkopen, inclusief het fiscale effect. De canon is aftrekbaar, de rente op de lening ook, maar de bedragen en looptijden verschillen.`}
  ]},
 {id:'vbe-068',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-07T16:55:00',views:39,tags:['schenking','aflossen','renteaftrek'],beste:null,
  titel:'Schenking voor aflossing hypotheek: invloed op aftrek?',
  body:`Ouders schenken hun kind een bedrag dat het kind gebruikt om af te lossen. Heeft dat gevolgen voor de renteaftrek van de rest van de hypotheek?`,
  antwoorden:[
   {id:'vbe-068-a1',auteur:'u2',datum:'2026-06-07T21:35:00',rA:{},rAdv:{},body:`De aftrek op het restant blijft in beginsel gewoon bestaan, alleen wordt de aftrekbare rente lager door de lagere schuld. Na een extra aflossing kan het fiscale aflossingsschema worden herrekend. Voor de schenking zelf gelden de regels van de schenkbelasting, verwijs naar de actuele vrijstellingen.
Leg vast hoe de aflossing is verwerkt.`},
   {id:'vbe-068-a2',auteur:'u1',datum:'2026-06-08T12:40:00',rA:{},rAdv:{},body:`Vraag de klant de schenking schriftelijk vast te leggen. Dat helpt bij latere vragen van de Belastingdienst.`}
  ]},
 {id:'vbe-069',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-09T18:45:00',views:96,tags:['aangifte','eigenwoningreserve','controle'],beste:'vbe-069-a1',
  titel:'Waarom staat de eigenwoningreserve niet in de aangifte?',
  body:`Een klant zegt dat hij bij de vorige aangifte geen eigenwoningreserve heeft opgegeven, terwijl hij wel met overwaarde heeft verkocht. Wat raad ik aan?`,
  antwoorden:[
   {id:'vbe-069-a1',auteur:'u5',datum:'2026-06-10T11:30:00',rA:{u4:4,u6:5,u2:3,u7:5},rAdv:{u4:4,u6:5,u7:5},body:`De eigenwoningreserve is relevant voor de berekening van de eigenwoningschuld bij de volgende aankoop. Als die niet goed is verwerkt, kan de aftrek te hoog zijn. Adviseer de klant om de aangifte te laten controleren en zo nodig te corrigeren.
Leg in het dossier vast welke gegevens je gebruikt hebt en dat je de klant hierop hebt gewezen.`},
   {id:'vbe-069-a2',auteur:'u8',datum:'2026-06-10T23:50:00',rA:{u3:4,u2:4},rAdv:{},body:`Wees duidelijk dat het invullen van de aangifte de verantwoordelijkheid van de klant is, tenzij je dat als dienst levert. Leg de afbakening van je dienstverlening vast.`}
  ]},
 {id:'vbe-070',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-12T19:40:00',views:43,tags:['overgangsrecht','aflossen','aflossingsvrij'],beste:'vbe-070-a1',
  titel:'Aflossen op aflossingsvrij deel: overgangsrecht verloren?',
  body:`Een klant lost extra af op zijn aflossingsvrije deel onder het overgangsrecht. Hij wil later eventueel weer bijlenen. Krijgt hij het overgangsrecht dan terug?`,
  antwoorden:[
   {id:'vbe-070-a1',auteur:'u4',datum:'2026-06-13T03:45:00',rA:{u2:5,u8:4,u6:5},rAdv:{u2:5,u8:4},body:`Nee. Wat afgelost is op de bestaande eigenwoningschuld, komt niet terug onder het overgangsrecht. Leent hij later opnieuw, dan moet het nieuwe deel voldoen aan de aflossingseis. Bespreek dit voordat de klant aflost.
Leg vast dat je de klant hierop hebt gewezen.`},
   {id:'vbe-070-a2',auteur:'u2',datum:'2026-06-13T18:20:00',rA:{u8:5,u6:3,u4:5},rAdv:{u4:5},body:`Als de klant flexibiliteit wil houden, kan het zinvoller zijn eerst af te lossen op een ander leningdeel. Kijk naar de rente per leningdeel en het fiscale effect.`}
  ]},
 {id:'vbe-071',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-18T09:20:00',views:177,tags:['nieuwbouw','bouwrente','aftrek'],beste:null,
  titel:'Hypotheek bij woning in aanbouw: bouwrente aftrekbaar?',
  body:`Bij een nieuwbouwwoning betaalt de klant bouwrente aan de projectontwikkelaar. Is die bouwrente aftrekbaar?`,
  antwoorden:[
   {id:'vbe-071-a1',auteur:'u1',datum:'2026-06-19T01:20:00',rA:{u4:3,u8:3,u2:3,u3:4},rAdv:{u4:3,u8:3,u2:3},body:`Bouwrente kan onder voorwaarden tot de verwervingskosten van de woning horen. De rente die tijdens de bouw over de lening en het bouwdepot wordt betaald, is in de regel aftrekbaar als de woning binnen de termijn hoofdverblijf wordt. Controleer de koop- en aannemingsovereenkomst en de actuele regels.
Leg de opleverplanning vast.`}
  ]},
 {id:'vbe-072',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-20T10:05:00',views:111,tags:['uitzending','eigen woning','tijdelijk'],beste:null,
  titel:'Aftrek bij tijdelijke uitzending naar het buitenland',
  body:`Een klant gaat twee jaar voor zijn werkgever naar het buitenland en laat de woning leeg staan. Blijft de woning eigen woning?`,
  antwoorden:[]},
 {id:'vbe-073',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-26T08:00:00',views:78,tags:['netto lasten','overgangsrecht','leningdelen'],beste:'vbe-073-a1',
  titel:'Netto lasten bij combinatie oud en nieuw leningdeel',
  body:`Ik maak een advies met een oud aflossingsvrij deel en een nieuw annuitair deel. De klant snapt de netto lasten niet. Hoe leggen jullie dit uit?`,
  antwoorden:[
   {id:'vbe-073-a1',auteur:'u1',datum:'2026-06-26T14:40:00',rA:{u8:3,u4:4},rAdv:{u4:4},body:`Ik maak per leningdeel een overzicht met bruto rente, aflossing, aftrek en netto last. Daarna tel ik ze op. Klanten zien dan dat het oude deel geen aflossing heeft, maar dat het nieuwe deel wel aflost.
Leg het overzicht vast als bijlage bij het rapport.`},
   {id:'vbe-073-a2',auteur:'u6',datum:'2026-06-27T10:40:00',rA:{u4:3,u7:5,u3:3},rAdv:{u4:3,u7:5},body:`In het adviespakket kun je de netto lasten per leningdeel tonen. Zet die weergave aan, dat helpt in het klantgesprek.`}
  ]},
 {id:'vbe-074',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-28T13:20:00',views:514,tags:['box 3','verkoop','eigenwoningreserve'],beste:'vbe-074-a1',
  titel:'Box 3-lening en eigen woning: verdeling bij verkoop',
  body:`Een klant heeft een hypotheek met een box 1- en een box 3-deel en verkoopt de woning. Hoe bereken ik de eigenwoningreserve?`,
  antwoorden:[
   {id:'vbe-074-a1',auteur:'u5',datum:'2026-06-29T05:50:00',rA:{u7:5},rAdv:{},body:`Bij de berekening van de eigenwoningreserve trek je alleen de eigenwoningschuld af van de verkoopopbrengst, niet het box 3-deel. Daardoor kan de reserve hoger zijn dan de klant verwacht. Leg de berekening vast.
Bespreek ook wat de klant met het box 3-deel doet bij een nieuwe aankoop.`},
   {id:'vbe-074-a2',auteur:'u4',datum:'2026-06-29T20:55:00',rA:{},rAdv:{},body:`Dit wordt vaak verkeerd ingeschat. Ik vraag altijd de jaaropgave op om de fiscale status per leningdeel vast te stellen.`}
  ]},
 {id:'vbe-075',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-04T09:00:00',views:223,tags:['advieskosten','oversluiten','financieringskosten'],beste:'vbe-075-a1',
  titel:'Advieskosten bij oversluiten aftrekbaar?',
  body:`Een klant sluit over en betaalt advieskosten en een taxatie. Zijn die kosten aftrekbaar, ook al koopt hij geen nieuwe woning?`,
  antwoorden:[
   {id:'vbe-075-a1',auteur:'u4',datum:'2026-07-05T05:40:00',rA:{u3:5,u2:5},rAdv:{u3:5},body:`Ja, kosten die je maakt om een eigenwoningschuld af te sluiten of over te sluiten zijn in de regel aftrekbaar als financieringskosten. Denk aan advies- en bemiddelingskosten, taxatie en notariskosten voor de hypotheekakte. Ze zijn aftrekbaar in het jaar van betaling.
Geef de klant een overzicht van de aftrekbare posten en bewaar de nota in het dossier.`},
   {id:'vbe-075-a2',auteur:'u5',datum:'2026-07-06T01:00:00',rA:{u8:3},rAdv:{},body:`Let op dat de kosten wel betrekking moeten hebben op het eigenwoningdeel. Bij een gecombineerde lening met een box 3-deel verdeel je de kosten naar verhouding.`}
  ]},
 {id:'vbe-076',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-07T17:15:00',views:535,tags:['NHG','financieringskosten','meefinancieren'],beste:null,
  titel:'NHG-kosten meefinancieren: eigenwoningschuld?',
  body:`Kan ik de borgtochtprovisie voor NHG meefinancieren als eigenwoningschuld? En is die provisie aftrekbaar?`,
  antwoorden:[
   {id:'vbe-076-a1',auteur:'u1',datum:'2026-07-08T13:10:00',rA:{},rAdv:{},body:`De borgtochtprovisie hoort bij de financieringskosten en is aftrekbaar in het jaar van betaling. Meefinancieren kan binnen de normen van NHG en de geldverstrekker. Het deel dat je meefinanciert, is eigenwoningschuld mits de lening aan de aflossingseis voldoet.
Controleer de actuele NHG-normen en leg de opbouw van de financiering vast.`}
  ]},
 {id:'vbe-077',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-10T07:45:00',views:388,tags:['overlijden','erfgenamen','leegstand'],beste:'vbe-077-a1',
  titel:'Leegstaande woning na overlijden: renteaftrek erfgenamen?',
  body:`Na het overlijden van een alleenstaande klant staat de woning leeg en is er nog een hypotheek. De erfgenamen vragen of zij renteaftrek hebben. Wat kan ik zeggen?`,
  antwoorden:[
   {id:'vbe-077-a1',auteur:'u5',datum:'2026-07-11T01:10:00',rA:{u4:3,u6:4,u1:5,u7:5},rAdv:{u4:3,u6:4,u1:5,u7:5},body:`Voor erfgenamen is de woning in de regel geen eigen woning, omdat zij er niet wonen. De woning en de schuld vallen dan bij hen in box 3. Voor de aangifte van de overledene gelden aparte regels.
Adviseer de erfgenamen om een fiscalist of notaris in te schakelen en leg vast dat je hebt doorverwezen.`},
   {id:'vbe-077-a2',auteur:'u8',datum:'2026-07-12T00:45:00',rA:{u5:5,u7:3},rAdv:{},body:`Wees voorzichtig met uitspraken over de nalatenschap. Dat valt vaak buiten je dienstverlening. Leg de afbakening vast.`}
  ]},
 {id:'vbe-078',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-14T10:55:00',views:360,tags:['fiscaal partner','verdeling','aangifte'],beste:null,
  titel:'Woning gekocht met partner, daarna fiscaal partnerschap',
  body:`Twee klanten kochten vorig jaar samen een woning en zijn dit jaar getrouwd. Kunnen ze de renteaftrek nu vrij verdelen?`,
  antwoorden:[
   {id:'vbe-078-a1',auteur:'u2',datum:'2026-07-15T10:05:00',rA:{u5:4,u7:4,u6:4},rAdv:{u5:4},body:`Als ze fiscaal partner zijn, mogen ze de rente en het forfait in hun aangifte vrij verdelen. Voor jaren waarin ze geen fiscaal partner waren, geldt de verdeling naar eigendom. Bij een huwelijk in de loop van het jaar kan onder voorwaarden voor het hele jaar partnerschap gelden, controleer de actuele regels.
Leg de trouwdatum en de verdeling vast.`},
   {id:'vbe-078-a2',auteur:'u1',datum:'2026-07-16T06:25:00',rA:{u6:5,u5:4},rAdv:{u6:5},body:`In de praktijk kiezen partners vaak om de aftrek bij de partner met het hoogste inkomen te leggen, maar door het beperkte aftrektarief is het voordeel kleiner dan vroeger. Laat het doorrekenen.`}
  ]},
 {id:'vbe-079',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-17T13:05:00',views:364,tags:['aflossingseis','looptijd','annuitair'],beste:'vbe-079-a1',
  titel:'Aflossingseis bij lening met kortere looptijd',
  body:`Een klant wil een lening met een looptijd van twintig jaar en een annuitaire aflossing. Voldoet die aan de aflossingseis?`,
  antwoorden:[
   {id:'vbe-079-a1',auteur:'u4',datum:'2026-07-18T00:40:00',rA:{u5:5},rAdv:{},body:`Ja. De eis is dat de lening binnen maximaal dertig jaar volledig wordt afgelost, ten minste annuitair. Een kortere looptijd met een volledige aflossing voldoet daar ruim aan. Bespreek wel de hogere maandlasten.
Leg de looptijd en het aflossingsschema vast.`}
  ]},
 {id:'vbe-080',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-19T23:50:00',views:211,tags:['aflossingsvrij','starter','box 3'],beste:'vbe-080-a1',
  titel:'Aflossingsvrij deel bij starter: echt geen aftrek?',
  body:`Een starter wil een deel aflossingsvrij lenen om de maandlast laag te houden. Klopt het dat de rente op dat deel niet aftrekbaar is?`,
  antwoorden:[
   {id:'vbe-080-a1',auteur:'u1',datum:'2026-07-20T07:15:00',rA:{u7:4,u3:5,u8:4,u6:4},rAdv:{u7:4},body:`Klopt. Voor nieuwe leningen na 2012 geldt de aflossingseis. Een aflossingsvrij deel voldoet daar niet aan en valt in box 3. De rente is niet aftrekbaar. Daarnaast hebben geldverstrekkers eigen grenzen voor aflossingsvrije delen.
Leg vast dat je de gevolgen hebt besproken.`},
   {id:'vbe-080-a2',auteur:'u2',datum:'2026-07-20T12:50:00',rA:{u7:3,u6:5,u8:5,u4:5},rAdv:{u8:5,u4:5},body:`Bespreek ook het risico dat er aan het einde van de looptijd een schuld blijft staan. Voor een starter is dat een belangrijk aandachtspunt.`}
  ]},
 {id:'vbe-081',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-24T16:40:00',views:292,tags:['levering','bewoning','aftrek'],beste:'vbe-081-a1',
  titel:'Hypotheekrente over periode tussen levering en bewoning',
  body:`Een klant krijgt de sleutel in maart maar verhuist pas in juni. Is de rente over die drie maanden aftrekbaar?`,
  antwoorden:[
   {id:'vbe-081-a1',auteur:'u4',datum:'2026-07-25T00:40:00',rA:{u7:4},rAdv:{},body:`Ja, als de woning in die periode leeg staat en bestemd is om binnen de termijn als hoofdverblijf te worden gebruikt, kan hij al als eigen woning gelden. Voorwaarde is dat de woning niet wordt verhuurd.
Leg de leveringsdatum en de verhuisdatum vast.`}
  ]},
 {id:'vbe-082',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-27T16:05:00',views:399,tags:['aftrekperiode','huren','30 jaar'],beste:null,
  titel:'Nieuwe hypotheek na huurperiode: aftrekperiode opnieuw?',
  body:`Een klant heeft jaren gehuurd na verkoop van een eerdere woning. Hij koopt nu weer. Begint de dertigjarige aftrekperiode opnieuw?`,
  antwoorden:[
   {id:'vbe-082-a1',auteur:'u5',datum:'2026-07-27T19:30:00',rA:{u1:3,u4:5,u6:4,u2:3},rAdv:{u1:3,u2:3},body:`Dat hangt af van de situatie. Eerder gebruikte aftrekjaren kunnen meetellen. Bij een volledig nieuwe eigenwoningschuld na een periode zonder eigen woning gelden specifieke regels voor de opgebouwde aftrekperiode. Controleer de fiscale historie via oude jaaropgaven en de actuele regels.
Leg vast hoe je de resterende aftrekperiode hebt bepaald.`},
   {id:'vbe-082-a2',auteur:'u6',datum:'2026-07-28T16:50:00',rA:{u2:4,u1:3},rAdv:{u1:3},body:`In het adviespakket kun je de reeds verbruikte aftrekmaanden vastleggen per leningdeel. Dat voorkomt een verkeerde einddatum van de aftrek.`}
  ]},
 {id:'vbe-083',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-31T14:35:00',views:507,tags:['box 3','schuldendrempel','restschuld'],beste:null,
  titel:'Box 3-schuld en schuldendrempel: hoe toelichten?',
  body:`Een klant heeft een box 3-restschuld en vraagt of hij daar belastingvoordeel van heeft in box 3. Hoe leg ik dat uit?`,
  antwoorden:[
   {id:'vbe-083-a1',auteur:'u2',datum:'2026-08-01T12:15:00',rA:{u1:5,u8:5,u3:5},rAdv:{u3:5},body:`Een box 3-schuld verlaagt het belaste vermogen, maar alleen het deel boven de schuldendrempel. De drempel en de berekening van box 3 zijn de laatste jaren gewijzigd, verwijs naar de actuele regels. Voor veel klanten is het effect beperkt.
Leg vast dat je dit hebt besproken.`},
   {id:'vbe-083-a2',auteur:'u5',datum:'2026-08-02T03:15:00',rA:{u6:4,u7:4},rAdv:{u7:4},body:`Gebruik voor de uitleg een eenvoudige berekening met de actuele normen. Klanten verwachten soms een voordeel dat er niet is.`}
  ]},
 {id:'vbe-084',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-03T22:45:00',views:267,tags:['kamerverhuur','student','vrijstelling'],beste:null,
  titel:'Kamer in eigen woning verhuren aan student',
  body:`Een klant met een ruime woning wil een kamer verhuren aan een student. Welke voorwaarden controleren jullie voordat je zegt dat dit fiscaal geen probleem is?`,
  antwoorden:[]},
 {id:'vbe-085',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-07T22:30:00',views:27,tags:['familie','aankoop','eigenwoningschuld'],beste:'vbe-085-a1',
  titel:'Woningruil binnen familie: eigenwoningschuld?',
  body:`Een klant koopt de woning van zijn ouders. Er wordt een deel geleend bij een geldverstrekker en een deel bij de ouders. Waar moet ik op letten?`,
  antwoorden:[
   {id:'vbe-085-a1',auteur:'u5',datum:'2026-08-08T08:50:00',rA:{u6:5,u1:5},rAdv:{},body:`Voor beide leningen geldt de aflossingseis om eigenwoningschuld te zijn. De familielening moet zakelijk zijn, met een schriftelijke overeenkomst, aflossingsschema en marktconforme rente. Ook de koopprijs moet zakelijk zijn, anders kan er sprake zijn van een schenking.
Leg de taxatie en de leningsovereenkomst vast.`},
   {id:'vbe-085-a2',auteur:'u2',datum:'2026-08-08T20:25:00',rA:{u6:3,u7:5,u5:5},rAdv:{u6:3},body:`Bespreek met ouders en kind de gevolgen voor de schenk- en erfbelasting. Adviseer zo nodig een notaris in te schakelen.`}
  ]},
 {id:'vbe-086',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-09T17:35:00',views:467,tags:['rentevaste periode','renteaftrek','looptijd'],beste:'vbe-086-a1',
  titel:'Renteaftrek na afloop van rentevaste periode',
  body:`Een klant heeft een rentevaste periode die afloopt. Verandert er iets aan de fiscale status als hij een nieuwe rentevaste periode kiest?`,
  antwoorden:[
   {id:'vbe-086-a1',auteur:'u4',datum:'2026-08-10T10:30:00',rA:{},rAdv:{},body:`Nee, een nieuwe rentevaste periode bij dezelfde lening verandert de fiscale status niet. De aftrekperiode en de aflossingseis blijven doorlopen. Alleen de rente wijzigt, en daarmee de aftrek.
Leg de nieuwe rente en periode vast.`},
   {id:'vbe-086-a2',auteur:'u1',datum:'2026-08-10T12:10:00',rA:{u2:5,u7:3,u5:5},rAdv:{u5:5},body:`Gebruik het moment voor een check: klopt het aflossingsschema nog en is de klant tevreden met de lasten? Dat is een goed moment voor een adviesgesprek.`}
  ]},
 {id:'vbe-087',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-13T18:00:00',views:111,tags:['eigenwoningreserve','meerdere verkopen','berekening'],beste:null,
  titel:'Eigenwoningreserve bij twee eerdere verkopen',
  body:`Een klant heeft binnen enkele jaren twee keer een woning verkocht met overwaarde. Hoe bereken ik de eigenwoningreserve voor de nieuwe aankoop?`,
  antwoorden:[
   {id:'vbe-087-a1',auteur:'u5',datum:'2026-08-13T19:55:00',rA:{u4:5,u2:5,u7:5,u6:4},rAdv:{u7:5},body:`Bij meerdere verkopen moet je per verkoop de reserve en de termijn bepalen. Een eerder ontstane reserve kan deels zijn ingezet bij de volgende woning. Werk het stap voor stap uit en controleer welke reserve nog binnen de termijn valt.
Leg de berekening per verkoop vast.`}
  ]},
 {id:'vbe-088',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-17T07:10:00',views:225,tags:['restschuld','aftrek','aflossen'],beste:'vbe-088-a1',
  titel:'Klant wil restschuld uit 2017 versneld aflossen',
  body:`Een klant heeft een aftrekbare restschuld uit 2017 en spaargeld. Is het verstandig om die restschuld versneld af te lossen?`,
  antwoorden:[
   {id:'vbe-088-a1',auteur:'u2',datum:'2026-08-18T03:45:00',rA:{u1:5},rAdv:{},body:`Dat hangt af van de rente, de netto kosten en de buffer van de klant. Omdat de rente nog aftrekbaar is, zijn de netto kosten lager dan bij een box 3-schuld. Maak een vergelijking en houd rekening met de resterende aftrekperiode.
Leg de afweging vast.`},
   {id:'vbe-088-a2',auteur:'u5',datum:'2026-08-18T23:35:00',rA:{u3:4,u7:5,u2:3,u1:3},rAdv:{},body:`Controleer ook of er een boeterente is bij aflossen. Bij restschuldfinanciering is dat per geldverstrekker verschillend.`}
  ]},
 {id:'vbe-089',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-20T12:10:00',views:216,tags:['overgangsrecht','verhuizen','goedkoper'],beste:'vbe-089-a1',
  titel:'Overgangsrecht bij verhuizing naar goedkopere woning',
  body:`Een klant met overgangsrecht verhuist naar een goedkopere woning. Kan hij het overgangsrecht meenemen, en zo ja tot welk bedrag?`,
  antwoorden:[
   {id:'vbe-089-a1',auteur:'u5',datum:'2026-08-21T12:30:00',rA:{u1:4,u2:4,u3:3,u7:3},rAdv:{u2:4,u3:3,u7:3},body:`Het overgangsrecht gaat mee tot maximaal het bedrag van de bestaande eigenwoningschuld, maar de nieuwe eigenwoningschuld is beperkt door de bijleenregeling. Als de nieuwe woning goedkoper is, past vaak niet het hele bedrag. Het deel dat niet past, verliest de status.
Maak de berekening en leg die vast.`},
   {id:'vbe-089-a2',auteur:'u4',datum:'2026-08-21T20:40:00',rA:{},rAdv:{},body:`Bespreek ook dat een lagere schuld niet erg hoeft te zijn. Maar de klant moet weten dat het overgangsrecht niet terugkomt.`}
  ]},
 {id:'vbe-090',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-23T22:40:00',views:506,tags:['compliance','dossier','afwijzing'],beste:'vbe-090-a1',
  titel:'Vastleggen bij klant die advies afwijst',
  body:`Een klant wil tegen mijn advies in een deel aflossingsvrij lenen, terwijl hij daardoor minder aftrek heeft. Hoe leg ik dit vast?`,
  antwoorden:[
   {id:'vbe-090-a1',auteur:'u8',datum:'2026-08-24T05:15:00',rA:{u5:3,u7:4},rAdv:{},body:`Leg vast welk advies je hebt gegeven, welke risicos je hebt besproken en wat de klant heeft besloten. Laat de klant bevestigen dat hij afwijkt van het advies. Dat kan in het rapport of in een aparte verklaring.
Controleer daarnaast of de gekozen oplossing nog binnen de passendheid valt.`},
   {id:'vbe-090-a2',auteur:'u1',datum:'2026-08-24T21:55:00',rA:{u6:4,u7:5},rAdv:{u7:5},body:`Ik voeg altijd een netto lastenoverzicht toe van beide varianten. Dan is het verschil zwart op wit vastgelegd.`}
  ]},
 {id:'vbe-091',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-27T13:30:00',views:285,tags:['recreatiewoning','bestemming','eigen woning'],beste:null,
  titel:'Aftrek bij hypotheek voor woning met recreatiebestemming',
  body:`Een klant wil permanent wonen in een woning met een recreatiebestemming. Kan dat een eigen woning zijn voor de renteaftrek?`,
  antwoorden:[
   {id:'vbe-091-a1',auteur:'u4',datum:'2026-08-28T01:55:00',rA:{u6:4,u3:3,u5:4},rAdv:{u6:4,u3:3,u5:4},body:`Voor de inkomstenbelasting gaat het om het feitelijk gebruik als hoofdverblijf. Het is dus niet uitgesloten dat zo een woning eigen woning is. Maar permanente bewoning is vaak niet toegestaan volgens het bestemmingsplan, en geldverstrekkers financieren dit meestal niet.
Leg de bestemming en de risicos vast.`}
  ]},
 {id:'vbe-092',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-30T17:55:00',views:20,tags:['eigenwoningreserve','volgorde','doorstromer'],beste:null,
  titel:'Verhuizen en eigenwoningreserve bij verkoop na aankoop',
  body:`Een klant koopt eerst een nieuwe woning en verkoopt daarna de oude. Telt de eigenwoningreserve van de latere verkoop dan nog mee voor de nieuwe lening?`,
  antwoorden:[]},
 {id:'vbe-093',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-02T20:00:00',views:109,tags:['vakantieverhuur','eigen woning','box 3'],beste:'vbe-093-a1',
  titel:'Woning deels verhuurd via vakantieverhuur',
  body:`Een klant verhuurt de woning een paar weken per jaar via een verhuurplatform als hij op vakantie is. Heeft dat gevolgen voor de eigenwoningstatus?`,
  antwoorden:[
   {id:'vbe-093-a1',auteur:'u5',datum:'2026-09-03T15:30:00',rA:{u4:3,u3:3},rAdv:{u3:3},body:`Kortdurende verhuur van de hele woning kan fiscale gevolgen hebben. De verhuuropbrengst moet in de regel worden aangegeven, en er zijn aparte regels voor hoe dat wordt belast. De woning blijft vaak wel hoofdverblijf, maar controleer de actuele regels.
Wijs de klant ook op de voorwaarden van de geldverstrekker en de gemeente.`},
   {id:'vbe-093-a2',auteur:'u3',datum:'2026-09-03T19:00:00',rA:{u5:3,u1:4,u2:4,u6:5},rAdv:{u5:3,u1:4,u2:4},body:`Check de woonhuisverzekering. Veel polissen sluiten schade tijdens verhuur uit of stellen extra voorwaarden.`}
  ]},
 {id:'vbe-094',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-06T14:10:00',views:126,tags:['scheiding','box 3','herfinanciering'],beste:'vbe-094-a1',
  titel:'Herfinanciering na scheiding: oude lening deels box 3?',
  body:`Na een scheiding blijft een partner in de woning en neemt de hele hypotheek over. Een deel van de oude lening was ooit opgenomen voor een auto. Hoe gaat dat fiscaal?`,
  antwoorden:[
   {id:'vbe-094-a1',auteur:'u5',datum:'2026-09-07T13:05:00',rA:{u6:3,u1:4,u8:3,u3:3},rAdv:{u6:3,u1:4,u8:3,u3:3},body:`Het deel dat destijds voor de auto is gebruikt, is geen eigenwoningschuld en blijft box 3. Neem dat over als apart leningdeel. Voor de rest van de schuld gelden de regels voor de overname van het aandeel van de ex-partner.
Leg de fiscale status van elk leningdeel vast op basis van de historie.`},
   {id:'vbe-094-a2',auteur:'u6',datum:'2026-09-08T11:05:00',rA:{},rAdv:{},body:`Controleer in het adviespakket of de box-indeling bij overname correct wordt overgenomen. Bij het kopieren van een dossier kan dit fout gaan.`}
  ]},
 {id:'vbe-095',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-11T09:10:00',views:218,tags:['lineair','annuitair','netto lasten'],beste:'vbe-095-a1',
  titel:'Starter vraagt naar fiscaal voordeel lineair',
  body:`Een starter vraagt of lineair aflossen fiscaal voordeliger is. Hoe leggen jullie dat uit?`,
  antwoorden:[
   {id:'vbe-095-a1',auteur:'u1',datum:'2026-09-11T16:05:00',rA:{u6:5},rAdv:{},body:`Bij lineair aflossen daalt de schuld sneller, waardoor de rente en daarmee de aftrek ook sneller dalen. Over de hele looptijd betaal je minder rente. Of dat voordeliger is, hangt af van de situatie. Laat de netto lasten over de looptijd zien.
Leg vast welke vorm de klant kiest en waarom.`}
  ]},
 {id:'vbe-096',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-13T20:40:00',views:414,tags:['uitstel','aflossingseis','betalingsregeling'],beste:null,
  titel:'Rente-aftrek bij uitstel van aflossing door geldverstrekker',
  body:`Een geldverstrekker biedt een klant met betalingsproblemen een tijdelijke aflossingsvrije periode aan. Wat betekent dat voor de renteaftrek?`,
  antwoorden:[
   {id:'vbe-096-a1',auteur:'u5',datum:'2026-09-14T21:00:00',rA:{u4:3,u8:5,u6:4},rAdv:{u4:3,u8:5,u6:4},body:`Als de aflossing tijdelijk niet wordt betaald, ontstaat er een aflossingsachterstand. Die moet binnen de fiscale termijn worden ingehaald om de aftrek te behouden. Controleer de actuele regels en bespreek met de klant hoe de achterstand wordt ingehaald.
Leg de afspraak met de geldverstrekker vast.`},
   {id:'vbe-096-a2',auteur:'u8',datum:'2026-09-15T12:40:00',rA:{u4:4,u5:5},rAdv:{u4:4},body:`Bij betalingsproblemen is zorgvuldigheid extra belangrijk. Leg vast dat je de fiscale gevolgen hebt besproken.`}
  ]},
 {id:'vbe-097',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-16T09:55:00',views:475,tags:['overgangsrecht','samenwonen','nieuwe partner'],beste:'vbe-097-a1',
  titel:'Aflossingsvrij oversluiten van oude naar nieuwe partner',
  body:`Een klant met een aflossingsvrije lening gaat samenwonen. De nieuwe partner wordt mede-eigenaar en mede-schuldenaar. Krijgt de nieuwe partner ook overgangsrecht?`,
  antwoorden:[
   {id:'vbe-097-a1',auteur:'u5',datum:'2026-09-17T02:45:00',rA:{u2:5},rAdv:{u2:5},body:`Nee, de nieuwe partner heeft geen eigen overgangsrecht. Het overgangsrecht blijft bij de klant voor zijn deel van de bestaande schuld. Voor het deel dat de partner nieuw leent, geldt de aflossingseis.
Leg de verdeling van eigendom en schuld vast.`},
   {id:'vbe-097-a2',auteur:'u2',datum:'2026-09-17T12:50:00',rA:{},rAdv:{},body:`Bespreek ook wat er gebeurt bij een breuk. Een samenlevingscontract en duidelijke afspraken zijn belangrijk.`}
  ]},
 {id:'vbe-098',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-20T15:35:00',views:332,tags:['overgangsrecht','verhuur','herleven'],beste:null,
  titel:'Overgangsrecht na verhuurperiode van de woning',
  body:`Een klant heeft zijn woning enkele jaren verhuurd en gaat er nu weer zelf wonen. Herleeft het overgangsrecht?`,
  antwoorden:[]},
 {id:'vbe-099',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-24T11:15:00',views:200,tags:['aangifte','jaaropgave','controle'],beste:'vbe-099-a1',
  titel:'Hypotheekrente in aangifte: jaaropgave controleren',
  body:`Een klant vraagt me de jaaropgave te controleren voordat hij aangifte doet. Waar letten jullie op?`,
  antwoorden:[
   {id:'vbe-099-a1',auteur:'u1',datum:'2026-09-25T06:55:00',rA:{u3:4,u2:5,u4:4},rAdv:{u3:4,u2:5,u4:4},body:`Ik controleer:
- of de betaalde rente klopt met de leningdelen
- of de box-indeling per leningdeel juist is
- of er een eigenwoningreserve of overgangsrecht speelt
Leg vast dat je de controle hebt gedaan en wat je hebt gevonden.`},
   {id:'vbe-099-a2',auteur:'u8',datum:'2026-09-26T02:45:00',rA:{u5:3,u1:4},rAdv:{u5:3},body:`Maak duidelijk wat je wel en niet controleert. Dat voorkomt misverstanden over aansprakelijkheid.`}
  ]},
 {id:'vbe-100',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-26T10:45:00',views:456,tags:['verbouwing','box 3','omzetten'],beste:null,
  titel:'Verbouwing gefinancierd met box 3-lening: later omzetten?',
  body:`Een klant heeft een verbouwing gefinancierd met een persoonlijke lening. Kan die later worden omgezet in eigenwoningschuld?`,
  antwoorden:[
   {id:'vbe-100-a1',auteur:'u4',datum:'2026-09-27T02:05:00',rA:{u2:3,u3:3},rAdv:{},body:`In de regel niet, omdat de nieuwe lening dan niet wordt gebruikt voor de verbouwing maar voor de aflossing van een andere lening. Er zijn situaties waarin de oorspronkelijke lening al eigenwoningschuld kan zijn, als die aan de voorwaarden voldoet. Controleer de actuele regels.
Leg de historie vast.`}
  ]}
]);
